        private readonly ITableQuery _tableQuery;

        public AdminController(IOrderQuery orderQuery, ITableQuery tableQuery)
        {
            _orderQuery = orderQuery;
            _tableQuery = tableQuery;
        }

        [HttpGet("top-three-today")]
