            return HandleResult(result);
        }

        [HttpGet("pending-count-orders")]
        public async Task GetCountOfPendingOrders()
        {
            var result = await _orderQuery.GetCountOfPendingOrder();
            return HandleResult(result);
        }

        [HttpGet("total-count-orders")]
        public async Task GetCountOfOrders()
        {
            var result = await _orderQuery.GetCountOfOrders();
            return HandleResult(result);
        }

        [HttpGet("total-count-table")]
        public async Task GetCountOfTaple()
        {
            var result = await _tableQuery.GetCountTable();
            return HandleResult(result);
        }

        [HttpGet("historical-bills")]
        public async Task GetHistoricalBills(
            [FromQuery] DateTime startDate,
            [FromQuery] DateTime endDate,
            [FromQuery] PageDTO page)
        {

            var result = await _orderQuery.GetHistoricalBillsAsync(startDate, endDate, page);
            return HandleResult(result);
        }
    }
}

﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Authentication;
using OrderingSystem.WebApi.Controllers.Base;
using System.Threading.Tasks;

namespace OrderingSystem.WebApi.Controllers
{
    [ApiController]
    [Route("api/auth")]
    public class AuthController : BaseController
    {
        private readonly IAuthCommandService _authCommandService;

        public AuthController(IAuthCommandService authCommandService)
        {
            _authCommandService = authCommandService;
        }

        [HttpPost("login")]
        [EnableRateLimiting("LoginPolicy")]
        public async Task Login([FromBody] LoginRequest request)
        {
            var result = await _authCommandService.LoginAsync(request);
            return HandleResult(result);
        }

        [Authorize(Policy = "AdminOnly")]
        [HttpPost("register")]
        public async Task CreateUser([FromBody] CreateUserRequest request)
        {
            var result = await _authCommandService.CreateUserAsync(request);

            return HandleResult(result);
        }

        [HttpPost("refresh-token")]
        public async Task RefreshToken([FromBody] RefreshTokenRequest request)
        {
            var result = await _authCommandService.RefreshTokenAsync(request);
            return HandleResult(result);
        }

        [Authorize]
        [HttpPut("profile")]
        public async Task UpdateProfile([FromBody] UpdateProfileRequest request)
        {
            if (!CurrentUserId.HasValue) return Unauthorized(new { error = "Invalid token claims." });

            var result = await _authCommandService.UpdateProfileAsync(CurrentUserId.Value, request);
            return HandleResult(result);
        }

        [Authorize]
        [HttpPost("logout")]
        public async Task Logout()
        {
            if (!CurrentUserId.HasValue) return Unauthorized(new { error = "Invalid token claims." });

            // Extract the raw Bearer token from the header
            var token = Request.Headers.Authorization.ToString().Replace("Bearer ", "").Trim();

            var result = await _authCommandService.LogoutAsync(CurrentUserId.Value, token);
            return HandleResult(result);
        }
    }
}

﻿using Microsoft.AspNetCore.Http.HttpResults;
using Microsoft.AspNetCore.Mvc;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Enums;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

namespace OrderingSystem.WebApi.Controllers.Base
{
    [ApiController]
    [Produces("application/problem+json")]
    [Route("api/[controller]")]
    public abstract class BaseController : ControllerBase
    {
        // ── Property: Secure User Extraction ──────────────────────────────
        protected int? CurrentUserId
        {
            get
            {
                var userIdClaim = User.FindFirst(ClaimTypes.NameIdentifier) ??
                                  User.FindFirst(JwtRegisteredClaimNames.Sub);

                if (userIdClaim != null && int.TryParse(userIdClaim.Value, out int userId))
                {
                    return userId;
                }
                return null;
            }
        }

        // ── Property: Secure Device Session Extraction ────────────────────
        protected Guid? CurrentDeviceSessionId
        {
            get
            {
                // 1. Primary Secure Approach: Extract from the validated JWT Claims
                var sessionClaim = User.FindFirst("DeviceSessionId")?.Value;
                if (!string.IsNullOrEmpty(sessionClaim) && Guid.TryParse(sessionClaim, out var claimSessionId))
                {
                    return claimSessionId;
                }

                // 2. Web Fallback: Try to read from Cookies (Standard Browsers)
                if (Request.Cookies.TryGetValue("DeviceSessionId", out var cookieValue) &&
                    Guid.TryParse(cookieValue, out var deviceSessionId))
                {
                    return deviceSessionId;
                }

                // 3. Manual Header Fallback (Legacy Safari workaround)
                if (Request.Headers.TryGetValue("x-device-session-id", out var headerValue) &&
                    Guid.TryParse(headerValue, out var headerSessionId))
                {
                    return headerSessionId;
                }

                return null;
            }
        }

        // ── Method: Standard Result Mapping (200 OK / 204 No Content) ─────
        protected IActionResult HandleResult(Result result)
        {
            if (result.IsSuccess)
            {
                return result.Value == null ? NoContent() : Ok(result.Value);
            }

            return MapError(result.ErrorType, result.ErrorMessage);
        }

        protected IActionResult HandleResult(Result result)
        {
            if (result.IsSuccess)
            {
                return NoContent();
            }

            return MapError(result.ErrorType, result.ErrorMessage);
        }

        // ── Method: Created Result Mapping (201 CreatedAtAction) ──────────
        protected IActionResult HandleCreatedResult(Result result, string actionName, object routeValues)
        {
            if (result.IsSuccess)
            {
                return CreatedAtAction(actionName, routeValues, result.Value);
            }

            return MapError(result.ErrorType, result.ErrorMessage);
        }

        // ── Helper: Unified Error Mapping ─────────────────────────────────
        private IActionResult MapError(enErrorType errorType, string? errorMessage)
        {
            var statusCode = errorType switch
            {
                enErrorType.Validation => StatusCodes.Status400BadRequest,
                enErrorType.NotFound => StatusCodes.Status404NotFound,
                enErrorType.Conflict => StatusCodes.Status409Conflict,
                enErrorType.Unauthorized => StatusCodes.Status401Unauthorized,
                enErrorType.BalanceViolation => StatusCodes.Status422UnprocessableEntity,
                enErrorType.Failure => StatusCodes.Status500InternalServerError,
                _ => StatusCodes.Status500InternalServerError
            };

            var title = errorType switch
            {
                enErrorType.Validation => "Validation Error",
                enErrorType.NotFound => "Resource Not Found",
                enErrorType.Conflict => "Conflict",
                enErrorType.Unauthorized => "Unauthorized",
                enErrorType.BalanceViolation => "Business Rule Violation",
                enErrorType.Failure => "Server Error",
                _ => "An unexpected error occurred"
            };

            if (errorType== enErrorType.Validation)
            {
                // We create a dictionary to fit the requirement of ValidationProblemDetails
                var errors = new Dictionary
        {
            { "BusinessRule", new[] { errorMessage ?? "Validation failed" } }
        };

                return ValidationProblem(new ValidationProblemDetails(errors)
                {
                    Status = statusCode,
                    Title = "Validation Error",
                    Detail = errorMessage
                });
            }

            // The Problem() method automatically formats the response as a standard application/problem+json ProblemDetails object
            return Problem(
                statusCode: statusCode,
                title: title,
                detail: errorMessage
            );
        }
    }
}

﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.DTOs.Paged;
using OrderingSystem.Application.Interfaces.Category;
using OrderingSystem.WebApi.Controllers.Base;
using System.Threading.Tasks;

namespace OrderingSystem.WebApi.Controllers
{
    [ApiController]
    [Route("api/categories")]
    public class CategoriesController : BaseController
    {
        private readonly ICategoryCommandService _categoryCommandService;
        private readonly ICategoryQuery _categoryQueryService;

        public CategoriesController(
            ICategoryCommandService categoryCommandService,
            ICategoryQuery categoryQueryService)
        {
            _categoryCommandService = categoryCommandService;
            _categoryQueryService = categoryQueryService;
        }

        [Authorize(Policy = "AdminOnly")]
        [HttpPost]
        public async Task AddCategory([FromBody] CategoriesRecords.AddCategoryRequest request)
        {
            var result = await _categoryCommandService.AddCategoryAsync(request);

            return HandleCreatedResult(
                result,
                nameof(GetCategoryById),
                new { id = result.Value?.CategoryId }
            );
        }

        [Authorize(Policy = "AdminOnly")]
        [HttpPut]
        public async Task UpdateCategory([FromBody] CategoriesRecords.UpdateCategoryRequest request)
        {
            var result = await _categoryCommandService.UpdateCategoryAsync(request);
            return HandleResult(result);
        }

        [Authorize(Policy = "AdminOnly")]
        [HttpDelete]
        public async Task DeleteCategory([FromBody] CategoriesRecords.DeleteCategoryRequest request)
        {
            var result = await _categoryCommandService.DeleteCategoryAsync(request);
            return HandleResult(result);
        }
        [HttpGet("{id}")]
        public async Task GetCategoryById(int id)
        {
            var result = await _categoryQueryService.GetCategoryByIdAsync(id);
            return HandleResult(result);
        }
        [HttpGet("details/{id}")]
        public async Task GetCategory(int id)
        {
            var result = await _categoryQueryService.GetCategoryAsync(id);
            return HandleResult(result);
        }

        [HttpGet]
        public async Task GetAllCategories([FromQuery] PageDTO page)
        {
            var result = await _categoryQueryService.GetAllCategoriesAsync(page);
            return HandleResult(result);
        }

        [HttpGet("available")]
        public async Task GetAllAvailableCategories([FromQuery] PageDTO page)
        {
            var result = await _categoryQueryService.GetAllAvailableCategoriesAsync(page);
            return HandleResult(result);
        }
    }
}

﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.DTOs.Paged;
using OrderingSystem.Application.Interfaces.MenueItem;
using OrderingSystem.WebApi.Controllers.Base;
using System.Threading.Tasks;

namespace OrderingSystem.WebApi.Controllers
{
    [ApiController]
    [Route("api/menu-items")]
    public class MenuItemsController : BaseController
    {
        private readonly IMenueItemCommandService _menuItemCommandService;
        private readonly IMenueItemQuery _menuItemQueryService;

        public MenuItemsController(
            IMenueItemCommandService menuItemCommandService,
            IMenueItemQuery menuItemQueryService)
        {
            _menuItemCommandService = menuItemCommandService;
            _menuItemQueryService = menuItemQueryService;
        }

        [Authorize(Policy = "AdminOnly")]
        [HttpPost]
        public async Task AddMenuItem([FromBody] MenuRecords.AddMenuItemRequest request)
        {
            var result = await _menuItemCommandService.AddMenuItemAsync(request);

            return HandleCreatedResult(
                result,
                nameof(GetItemById),
                new { id = result.Value?.MenuItemId }
            );
        }

