namespace OrderingSystem.WebApi.Controllers
{
    [ApiController]
    [Route("api/orders")]
    public class OrdersController : BaseController
    {
        private readonly IOrderCommandService _orderCommandService;
        private readonly IOrderQuery _orderQuery;

        public OrdersController(IOrderCommandService orderCommandService, IOrderQuery orderQuery)
        {
            _orderCommandService = orderCommandService;
            _orderQuery = orderQuery;
        }

        [HttpPost]
        public async Task CreateOrder([FromBody] OrderRecords.CreateOrderRequest request)
        {
            if (!CurrentDeviceSessionId.HasValue)
            {
                return Unauthorized(new { error = "Invalid or missing device session." });
            }

            var result = await _orderCommandService.AddOrderAsync(request, CurrentDeviceSessionId.Value);

            return HandleCreatedResult(
                result,
                nameof(CreateOrder),
                new { id = result.Value?.OrderId }
            );
        }

        [HttpPut("{id}/approve")]
        [Authorize(Policy = "RequireStaff")]
        public async Task ApproveOrder(int id)
