            var result = await _orderCommandService.ApproveOrderAsync(id);
            return HandleResult(result);
        }

        [HttpDelete("{id}/cancel")]
        [Authorize(Policy = "RequireStaff")]
        public async Task CancelOrder(int id)
        {
            var result = await _orderCommandService.CancelOrderAsync(id);
            return HandleResult(result);
        }

        [HttpDelete("{id}/customer-cancel")]
        public async Task CustomerCancelOrder(int id)
        {
            if (!CurrentDeviceSessionId.HasValue)
            {
                return Unauthorized(new { error = "Invalid or missing device session." });
            }

            var result = await _orderCommandService.CancelOrderByCustomerAsync(id, CurrentDeviceSessionId.Value);
            return HandleResult(result);
        }

        [HttpGet("pending")]
        [Authorize(Policy = "RequireStaff")]
        public async Task GetPendingOrders([FromQuery] PageDTO page)
        {
            var result = await _orderQuery.GetPendingOrdersAsync(page);
            return HandleResult(result);
        }

        [HttpGet("historical-bills")]
        [Authorize(Policy = "RequireStaff")]
        public async Task GetHistoricalBills(
         [FromQuery] DateTime startDate,
         [FromQuery] DateTime endDate,
             [FromQuery] PageDTO page)
        {
            var result = await _orderQuery.GetHistoricalBillsAsync(startDate, endDate, page);
            return HandleResult(result);
        }

    }
}

﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Authentication;
using OrderingSystem.Application.Interfaces.TableSessionInterfaces;
using OrderingSystem.Domain.Enums;
using OrderingSystem.WebApi.Controllers.Base;

namespace OrderingSystem.WebApi.Controllers
{
    [ApiController]
    [Route("api/tables/sessions")]
    public class TableSessionsController : BaseController
    {
        private readonly ISessionCommandService _sessionCommandService;
        private readonly ITableSessionQuery _sessionQueryService;

        public TableSessionsController(
            ISessionCommandService sessionCommandService,
            ITableSessionQuery sessionQueryService)
        {
            _sessionCommandService = sessionCommandService;
            _sessionQueryService = sessionQueryService;
        }

        // 1. WRITE ENDPOINT (Command Path)

        // ── CUSTOMER PATH: Scan the QR code ─────────────────────────────────────
        [HttpPost("qr")]
        public async Task ProcessQrCode([FromBody] ProcessQrCodeRequest request)
        {
            var result = await _sessionCommandService.ProcessTableQrCodeAsync(request.qrCode, CurrentDeviceSessionId);

            if (result.IsSuccess && result.Value?.DeviceSession != null)
            {
                var cookieOptions = new CookieOptions
                {
                    HttpOnly = true,
                    Secure = true,
                    SameSite = SameSiteMode.None,
                    Expires = DateTime.UtcNow.AddHours(4),
                    MaxAge = TimeSpan.FromHours(4),
                    IsEssential = true
                };

                // LGACY COOKIE LOGIC (Less Secure, but working if there was any problems with the JWTs)
                // Response.Cookies.Append("DeviceSessionId", result.Value.DeviceSession.DeviceSessionId.ToString(), cookieOptions);

                var jwtProvider = HttpContext.RequestServices.GetRequiredService();
                var signalRToken = jwtProvider.GenerateCustomerSignalRToken(
                    result.Value.DeviceSession.DeviceSessionId,
                    result.Value.TableSession.TableSessionId
                );

                Response.Cookies.Append("SignalRContext", signalRToken, cookieOptions);

                return Ok(new
                {
                    tableSession = result.Value.TableSession,
                    deviceSession = result.Value.DeviceSession,
                    accessToken = signalRToken
                });
            }

            return HandleResult(result);
        }

        // ── CASHIER PATH: Approve the activation request ────────────────────────
        [Authorize(Policy = "RequireStaff")]
        [HttpPost("activate")]
        public async Task ActivateTableSession([FromBody] ActivateTableSessionRequest request)
        {
            var result = await _sessionCommandService.ActivateTableSessionAsync(request);
            return HandleResult(result);
        }

        // ── CUSTOMER PATH: Approve the guests ───────────────────────────────────
        [HttpPost("approve")]
        public async Task ApproveGuest([FromBody] ApproveJoiningSessionRequest request)
        {
            if (!CurrentDeviceSessionId.HasValue)
                return Unauthorized(new { error = "Invalid or missing device session." });

            var result = await _sessionCommandService.ApproveJoiningRequestAsync(request, CurrentDeviceSessionId.Value);
            return HandleResult(result);
        }

        // ── CUSTOMER PATH: Request the bill ─────────────────────────────────────
        [HttpPost("request-bill")]
        public async Task RequestBill([FromBody] RequestBillRequest request)
        {
            if (!CurrentDeviceSessionId.HasValue)
            {
                return Unauthorized(new { error = "Invalid or missing device session." });
            }

            var result = await _sessionCommandService.RequestBillAsync(request.tableSessionId, CurrentDeviceSessionId.Value);
            return HandleResult(result);
        }

        // ── CUSTOMER PATH: Reject the guest ─────────────────────────────────────
        [HttpPost("reject")]
        public async Task RejectGuest([FromBody] ApproveJoiningSessionRequest request)
        {
            if (!CurrentDeviceSessionId.HasValue)
                return Unauthorized(new { error = "Invalid or missing device session." });

            var result = await _sessionCommandService.RejectJoiningRequestAsync(request.deviceSessionId, CurrentDeviceSessionId.Value);
            return HandleResult(result);
        }

        // ── CASHIER PATH: Close session after payment ───────────────────────────
        [Authorize(Policy = "RequireStaff")]
        [HttpPost("end")]
        public async Task EndTableSession([FromBody] ActivateTableSessionRequest request)
        {
            // Reusing ActivateTableSessionRequest since it only contains the TableSessionId
            var result = await _sessionCommandService.EndTableSessionAsync(request.tableSessionId);
            return HandleResult(result);
        }

        [HttpGet("{tableSessionId}/bill")]
        public async Task GetBillSummary(Guid tableSessionId)
        {
            // 1. Check if the user is a Staff member (Admin or Cashier)
            bool isStaff = User.IsInRole(enRoleType.Admin.ToString()) ||
                           User.IsInRole(enRoleType.Cashier.ToString());

            // 2. If not staff, enforce strict device session validation
            if (!isStaff)
            {
                if (!CurrentDeviceSessionId.HasValue)
                    return Unauthorized(new { error = "Invalid or missing device session." });

                var status = await _sessionQueryService.GetSessionPollingStatusAsync(tableSessionId, CurrentDeviceSessionId.Value);
                if (status == null || !status.IsDeviceApproved)
                    return Unauthorized(new { error = "You must be approved by the host to view table data." });
            }

            // 3. Fetch and return the bill
            var result = await _sessionQueryService.GetBillSummaryAsync(tableSessionId);

            if (result == null)
                return NotFound(new { error = $"No bill found for session ID {tableSessionId}." });

            return Ok(result);
        }

        [Authorize(Policy = "RequireStaff")]
        [HttpPost("dismiss")]
        public async Task DismissTableSession([FromBody] ActivateTableSessionRequest request)
        {
            var result = await _sessionCommandService.DismissTableSessionAsync(request.tableSessionId);
            return HandleResult(result);
        }

        [Authorize(Policy = "RequireStaff")]
        [HttpPost("dismiss-bill")]
        public async Task DismissBill([FromBody] ActivateTableSessionRequest request)
        {
            var result = await _sessionCommandService.DismissBillAsync(request.tableSessionId);
            return HandleResult(result);
        }

        // 2. READ ENDPOINT (Query Path)
        [Authorize(Policy = "RequireStaff")]
        [HttpGet("active/{tableId}")]
        public async Task GetActiveSession(int tableId)
        {
            // Keeping standard Ok/NotFound since the Query returns a raw response, not Result
            var response = await _sessionQueryService.GetActiveSessionByTableAsync(tableId);
            if (response == null) return NotFound(new { error = $"No active session found for table ID {tableId}." });

            return Ok(response);
        }

        [HttpGet("{tableSessionId}/status")]
        public async Task GetSessionPollingStatus(Guid tableSessionId)
        {
            if (!CurrentDeviceSessionId.HasValue)
            {
                return Unauthorized(new { error = "Invalid or missing device session." });
            }

            var result = await _sessionQueryService.GetSessionPollingStatusAsync(tableSessionId, CurrentDeviceSessionId.Value);

            if (result == null)
            {
                return NotFound(new { error = "Session or device not found." });
            }

            return Ok(result);
        }
    }
}

﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.DTOs.Paged;
using OrderingSystem.Application.Interfaces.TableInterfaces;
using OrderingSystem.Domain.Enums;
using System.Threading.Tasks;

namespace OrderingSystem.WebApi.Controllers
{
    [ApiController]
    [Route("api/tables")]
    [Authorize(Policy = "RequireStaff")]
    public class TablesController : ControllerBase
    {
        private readonly ITableCommandService _tableCommandService;
        private readonly ITableQuery _tableQueryService;

        public TablesController(ITableCommandService tableCommandService, ITableQuery tableQueryService)
        {
            _tableCommandService = tableCommandService;
            _tableQueryService = tableQueryService;
        }

        [HttpPost]
        public async Task AddTable([FromBody] AddTableRequest request)
        {
            var result = await _tableCommandService.AddTableAsync(request);
            if (!result.IsSuccess)
            {
                return result.ErrorType == enErrorType.Validation ? BadRequest(result.ErrorMessage) : StatusCode(500, result.ErrorMessage);
            }

            return CreatedAtAction(nameof(GetTableById), new { tableId = result.Value!.TableId }, result.Value);
        }

        [HttpPut]
        public async Task UpdateTable([FromBody] UpdateTableRequest request)
        {
            var result = await _tableCommandService.UpdateTableAsync(request);
            if (!result.IsSuccess)
            {
                if (result.ErrorType == enErrorType.NotFound) return NotFound(result.ErrorMessage);
                if (result.ErrorType == enErrorType.Validation) return BadRequest(result.ErrorMessage);
                return StatusCode(500, result.ErrorMessage);
            }
            return Ok(result.Value);
        }

        [HttpDelete("{tableId}")]
        public async Task DeleteTable(int tableId)
        {
            var result = await _tableCommandService.DeleteTableAsync(tableId);
            if (!result.IsSuccess)
            {
                if (result.ErrorType == enErrorType.NotFound) return NotFound(result.ErrorMessage);
                if (result.ErrorType == enErrorType.Validation) return BadRequest(result.ErrorMessage);
                return StatusCode(500, result.ErrorMessage);
            }
            return NoContent();
        }

        [HttpGet("{tableId}/qrcode")]
        public async Task GetQrCode(int tableId)
        {
            var qrCode = await _tableQueryService.GetTableQrCodeAsync(tableId);
            if (qrCode == null) return NotFound($"Table ID {tableId} not found.");

            return Ok(new { QrCode = qrCode });
        }

        [HttpGet("{tableId}")]
        public async Task GetTableById(int tableId)
        {
            var result = await _tableQueryService.GetTableByIdAsync(tableId);
            if (result == null) return NotFound($"Table ID {tableId} not found.");

            return Ok(result);
        }

        [HttpGet("floor/{floorNumber}/number/{tableNumber}")]
        public async Task GetTableByNumber(int tableNumber, int floorNumber)
        {
            var result = await _tableQueryService.GetTableByNumberAsync(tableNumber, floorNumber);
            if (result == null) return NotFound($"Table Number {tableNumber} on Floor {floorNumber} not found.");

            return Ok(result);
        }

        [HttpGet("floor/{floorNumber}")]
        public async Task GetAllTablesByFloor([FromQuery] PageDTO page, int floorNumber)
        {
            var result = await _tableQueryService.GetAllTablesByFloorAsync(page, floorNumber);
            return Ok(result);
        }

        [HttpGet]
        public async Task GetAllTables([FromQuery] PageDTO page)
        {
            var result = await _tableQueryService.GetAllTablesAsync(page);
            return Ok(result);
        }

        [HttpGet("status/{tableStatus}")]
        public async Task GetAllTablesByStatus([FromQuery] PageDTO page, enTableStatus tableStatus)
        {
            var result = await _tableQueryService.GetAllTablesByStatusAsync(page, tableStatus);
            return Ok(result);
        }

        [HttpGet("pending-activation")]
        public async Task GetAllPendingActivationTables([FromQuery] PageDTO page)
        {
            var result = await _tableQueryService.GetAllPendingActivationTablesAsync(page);
            return Ok(result);
        }

        [HttpGet("billing")]
        public async Task GetAllBillingTables([FromQuery] PageDTO page)
        {
            var result = await _tableQueryService.GetAllBillingTablesAsync(page);
            return Ok(result);
        }
    }
}

