﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Auth;
using OrderingSystem.Application.Interfaces.Authentication;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.IdentityModel.Tokens;
namespace OrderingSystem.Application.Services
{
    public class AuthCommandService : IAuthCommandService
    {
        private readonly IUserRepository _userRepository;
        private readonly IJwtProvider _jwtProvider;
        private readonly IMemoryCache _cache;

        public AuthCommandService(IUserRepository userRepository, IJwtProvider jwtProvider, IMemoryCache cache)
        {
            _userRepository = userRepository;
            _jwtProvider = jwtProvider;
            _cache = cache;
        }

        public async Task<Result> LoginAsync(LoginRequest request)
        {
            var user = await _userRepository.GetUserByFullNameAsync(request.FullName);

            if (user == null || !BCrypt.Net.BCrypt.EnhancedVerify(request.Password, user.PasswordHash))
            {
                return Result.Failure("Invalid credentials.", enErrorType.Unauthorized);
            }

            var (token, expiryTime) = _jwtProvider.GenerateToken(user);
            var refreshToken = _jwtProvider.GenerateRefreshToken();

            user.RefreshToken = refreshToken;
            user.RefreshTokenExpiryTime = DateTime.UtcNow.AddDays(7);
            user.AbsoluteRefreshTokenExpiryTime = DateTime.UtcNow.AddDays(30);
            await _userRepository.UpdateUserAsync(user);

            var response = new LoginResponse(token, refreshToken, expiryTime, user.FullName, user.Role);
            return Result.Success(response);
        }

        public async Task<Result> RefreshTokenAsync(RefreshTokenRequest request)
        {
            var principal = _jwtProvider.GetPrincipalFromExpiredToken(request.AccessToken);

            if (principal == null)
                return Result.Failure("Invalid access token.", enErrorType.Unauthorized);

            var userIdClaim = principal.FindFirst(ClaimTypes.NameIdentifier) ?? principal.FindFirst(JwtRegisteredClaimNames.Sub);
            if (userIdClaim == null || !int.TryParse(userIdClaim.Value, out int userId))
                return Result.Failure("Invalid token claims.", enErrorType.Unauthorized);

            var user = await _userRepository.GetUserByIdAsync(userId);

            if (user == null ||
                user.RefreshToken != request.RefreshToken ||
                user.RefreshTokenExpiryTime <= DateTime.UtcNow)
            {
                return Result.Failure("Invalid or expired refresh token.", enErrorType.Unauthorized);
            }

            if (user.AbsoluteRefreshTokenExpiryTime <= DateTime.UtcNow)
            {
                // Force them to log in again
                user.RefreshToken = null;
                await _userRepository.UpdateUserAsync(user);

                return Result.Failure("Session expired. Please log in again.", enErrorType.Unauthorized);
            }

            // Generate new rotated tokens
            var (newAccessToken, expiryTime) = _jwtProvider.GenerateToken(user);
            var newRefreshToken = _jwtProvider.GenerateRefreshToken();

            user.RefreshToken = newRefreshToken;
            user.RefreshTokenExpiryTime = DateTime.UtcNow.AddDays(7);
            await _userRepository.UpdateUserAsync(user);

            var response = new LoginResponse(newAccessToken, newRefreshToken, expiryTime, user.FullName, user.Role);
            return Result.Success(response);
        }

        public async Task<Result> CreateUserAsync(CreateUserRequest request)
        {
            if (await _userRepository.UserExistsAsync(request.FullName))
            {
                return Result.Failure("User already exists.", enErrorType.Conflict);
            }

            var newUser = new User
            {
                FullName = request.FullName,
                PasswordHash = BCrypt.Net.BCrypt.EnhancedHashPassword(request.Password),
                Role = request.Role
            };

            await _userRepository.AddUserAsync(newUser);

            var response = new UserResponse(newUser.UserId, newUser.FullName, newUser.Role);
            return Result.Success(response);
        }

        public async Task LogoutAsync(int userId, string token)
        {
            var user = await _userRepository.GetUserByIdAsync(userId);
            if (user == null) return Result.Failure("User not found.", enErrorType.NotFound);

            user.RefreshToken = null;
            user.RefreshTokenExpiryTime = null;
            user.AbsoluteRefreshTokenExpiryTime = null;
            await _userRepository.UpdateUserAsync(user);

            // Add the token to the blacklist cache for 15 minutes (matching token lifespan)
            _cache.Set($"blacklist_{token}", true, TimeSpan.FromMinutes(15));

            return Result.Success();
        }

        public async Task<Result> UpdateUserAsync(int userId, UpdateUserRequest request)
        {
            var user = await _userRepository.GetUserByIdAsync(userId);
            if (user == null) return Result.Failure("User not found.", enErrorType.NotFound);

            if (!string.IsNullOrWhiteSpace(request.FullName))
                user.FullName = request.FullName;

            if (request.Role.HasValue)
                user.Role = request.Role.Value;

            if (!string.IsNullOrWhiteSpace(request.Password))
                user.PasswordHash = BCrypt.Net.BCrypt.EnhancedHashPassword(request.Password);

            await _userRepository.UpdateUserAsync(user);
            return Result.Success(new UserResponse(user.UserId, user.FullName, user.Role));
        }

        public async Task<Result> DeleteUserAsync(int userId)
        {
            var user = await _userRepository.GetUserByIdAsync(userId);
            if (user == null) return Result.Failure("User not found.", enErrorType.NotFound);

            await _userRepository.DeleteUserAsync(user);
            return Result.Success(true);
        }

        public async Task<Result> UpdateProfileAsync(int userId, UpdateProfileRequest request)
        {
            var user = await _userRepository.GetUserByIdAsync(userId);
            if (user == null) return Result.Failure("User not found.", enErrorType.NotFound);

            if (!string.IsNullOrWhiteSpace(request.NewPassword))
            {
                if (string.IsNullOrWhiteSpace(request.CurrentPassword))
                    return Result.Failure("Current password is required to set a new password.", enErrorType.Validation);

                if (!BCrypt.Net.BCrypt.EnhancedVerify(request.CurrentPassword, user.PasswordHash))
                    return Result.Failure("Invalid current password.", enErrorType.Validation);

                user.PasswordHash = BCrypt.Net.BCrypt.EnhancedHashPassword(request.NewPassword);
            }
            else if (!string.IsNullOrWhiteSpace(request.CurrentPassword))
            {
                return Result.Failure("New password is required if you are providing your current password.", enErrorType.Validation);
            }

            if (!string.IsNullOrWhiteSpace(request.CurrentPassword) && !string.IsNullOrWhiteSpace(request.NewPassword))
            {
                if (!BCrypt.Net.BCrypt.EnhancedVerify(request.CurrentPassword, user.PasswordHash))
                    return Result.Failure("Invalid current password.", enErrorType.Validation);

                user.PasswordHash = BCrypt.Net.BCrypt.EnhancedHashPassword(request.NewPassword);
            }

            if (!string.IsNullOrWhiteSpace(request.FullName))
            {
                user.FullName = request.FullName;
            }

            await _userRepository.UpdateUserAsync(user);
            return Result.Success(true);
        }
    }
}

﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Category;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Application.Mappers;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Enums;
using System;
using System.Threading.Tasks;

namespace OrderingSystem.Application.Services
{
    public class CategoryCommandService : ICategoryCommandService
    {
        private readonly IRealTimeNotifier _realTimeNotifier;
         private Result ValidateCategoryRequest(string nameEn, string nameAr)
        {
            if (string.IsNullOrEmpty(nameAr) || string.IsNullOrEmpty(nameEn))
            {
                return Result.Failure("NameAr and NameEn cannot be null or empty.");
            }

            return Result.Success(null);
        }

        private readonly ICategoryRepository _categoryRepository;

        public CategoryCommandService(ICategoryRepository categoryRepository, IRealTimeNotifier realTimeNotifier)
        {
            _categoryRepository = categoryRepository;
            _realTimeNotifier = realTimeNotifier;

        }

        public async Task<Result> AddCategoryAsync(CategoriesRecords.AddCategoryRequest request)
        {
            if (request == null)
            {
                return Result.Failure("Request cannot be null.");
            }

            var validationResult = ValidateCategoryRequest(request.NameEn, request.NameAr);

            if (!validationResult.IsSuccess)
            {
                return Result.Failure(validationResult.ErrorMessage);
            }

            if (await _categoryRepository.CategoryIsExistsByNameAsync(request.NameEn, request.NameAr))
            {
                return Result.Failure(
                   $"A category with the name '{request.NameAr}' or '{request.NameEn}' already exists.",
                   enErrorType.Validation
               );
            }
           var category = CategoryMappers.ToEntity(request);

            if (category == null)
            {
                return Result.Failure("Failed to map request to entity.");
            }

            await _categoryRepository.AddCategoryAsync(category);
            await _realTimeNotifier.NotifyMenuUpdatedAsync();

            var response = category.ToResponse();
            return Result.Success(response);
        }

        public async Task<Result> UpdateCategoryAsync(  CategoriesRecords.UpdateCategoryRequest request)
        {
            if (request == null)
            {
                return Result.Failure("Request cannot be null.");
            }

            if (ValidateCategoryRequest(request.NameEn, request.NameAr).IsSuccess == false)
            {
                return Result.Failure("Invalid request data.");
            }

            if (request.CategoryId <= 0)
            {
                return Result.Failure("Invalid CategoryId.");
            }

            var existingCategory = await _categoryRepository.GetCategoryByIdAsync(request.CategoryId);
            if (existingCategory == null)
            {
                return Result.Failure($"Category with ID {request.CategoryId} not found.", enErrorType.NotFound);
            }

            existingCategory.NameAr = request.NameAr;
            existingCategory.NameEn = request.NameEn;
            existingCategory.IsAvailable = request.IsAvailable;

            await _categoryRepository.UpdateCategoryAsync(existingCategory);
            await _realTimeNotifier.NotifyMenuUpdatedAsync();

            var response = existingCategory.ToResponse();
            return Result.Success(response);
        }

        public async Task<Result> DeleteCategoryAsync(CategoriesRecords.DeleteCategoryRequest request)
        {
            if (request == null)
            {
                return Result.Failure("Request cannot be null.");
            }

            var existingCategory = await _categoryRepository.GetCategoryByIdAsync(request.CategoryId);
            if (existingCategory == null)
            {
                return Result.Failure($"Category with ID {request.CategoryId} not found.", enErrorType.NotFound);
            }

            bool hasActiveOrders = await _categoryRepository.HasActiveOrdersAsync(request.CategoryId);
            if (hasActiveOrders)
            {
                return Result.Failure(
                    "Cannot delete this category because it contains menu items that are currently part of active orders being prepared.",
                    enErrorType.Conflict);
            }

            await _categoryRepository.DeleteCategoryAsync(existingCategory);
            await _realTimeNotifier.NotifyMenuUpdatedAsync();

            return Result.Success(true);
        }
    }
}

﻿using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
using OrderingSystem.Application.Interfaces.Authentication;
using OrderingSystem.Domain.Entities;
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;

namespace OrderingSystem.Infrastructure.Authentication
{
    public class JwtProvider : IJwtProvider
    {
        private readonly IConfiguration _config;

        public JwtProvider(IConfiguration config)
        {
            _config = config;
        }

        public (string Token, DateTime ExpiryTime) GenerateToken(User user)
        {
            var jwtSettings = _config.GetSection("JwtSettings");
            var secretKey = jwtSettings["SecretKey"]!;

            var claims = new[]
            {
                new Claim(JwtRegisteredClaimNames.Sub, user.UserId.ToString()),
                new Claim(ClaimTypes.Role, user.Role.ToString())
            };

            var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
            var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

            var expiryTime = DateTime.UtcNow.AddMinutes(15);

            var token = new JwtSecurityToken(
                issuer: jwtSettings["Issuer"],
                audience: jwtSettings["Audience"],
                claims: claims,
                expires: expiryTime,
                signingCredentials: creds
            );

            var tokenString = new JwtSecurityTokenHandler().WriteToken(token);

            return (tokenString, expiryTime);
        }

        public string GenerateRefreshToken()
        {
            var randomNumber = new byte[32];
            using var rng = RandomNumberGenerator.Create();
            rng.GetBytes(randomNumber);
            return Convert.ToBase64String(randomNumber);
        }

        public ClaimsPrincipal? GetPrincipalFromExpiredToken(string token)
        {
            var jwtSettings = _config.GetSection("JwtSettings");
            var secretKey = jwtSettings["SecretKey"]!;

            var tokenValidationParameters = new TokenValidationParameters
            {
                ValidateAudience = true,
                ValidateIssuer = true,
                ValidIssuer = jwtSettings["Issuer"],
                ValidAudience = jwtSettings["Audience"],
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
                ValidateLifetime = false // Explicitly ignore expiry for extraction
            };

            var tokenHandler = new JwtSecurityTokenHandler();
            var principal = tokenHandler.ValidateToken(token, tokenValidationParameters, out SecurityToken securityToken);

            if (securityToken is not JwtSecurityToken jwtSecurityToken ||
                !jwtSecurityToken.Header.Alg.Equals(SecurityAlgorithms.HmacSha256, StringComparison.InvariantCultureIgnoreCase))
            {
                throw new SecurityTokenException("Invalid token format.");
            }

            return principal;
        }

        // Inside JwtProvider.cs
        public string GenerateCustomerSignalRToken(Guid deviceSessionId, Guid tableSessionId)
        {
            var jwtSettings = _config.GetSection("JwtSettings");
            var secretKey = jwtSettings["SecretKey"]!;
            var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
            var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

            // Embed both IDs directly into the claims
            var claims = new[]
            {
        new Claim("DeviceSessionId", deviceSessionId.ToString()),
        new Claim("TableSessionId", tableSessionId.ToString())
    };

            var token = new JwtSecurityToken(
                issuer: jwtSettings["Issuer"],
                audience: jwtSettings["Audience"],
                claims: claims,
                expires: DateTime.UtcNow.AddHours(4), // Match the cookie lifespan
                signingCredentials: creds
            );

            return new JwtSecurityTokenHandler().WriteToken(token);
        }

        public ClaimsPrincipal? ValidateCustomerSignalRToken(string token)
        {
            var jwtSettings = _config.GetSection("JwtSettings");
            var secretKey = jwtSettings["SecretKey"]!;

            var validationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidIssuer = jwtSettings["Issuer"],
                ValidAudience = jwtSettings["Audience"],
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),
                ValidateLifetime = true
            };

            try
            {
                return new JwtSecurityTokenHandler().ValidateToken(token, validationParameters, out _);
            }
            catch
            {
                return null; // Gracefully fail if token is tampered with or expired
            }
        }
    }
}

﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Category;
using OrderingSystem.Application.Interfaces.MenueItem;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Application.Mappers;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Enums;
using System;
using System.Collections.Generic;
using System.ComponentModel.Design;
using System.Text;

namespace OrderingSystem.Application.Services
{
    public class MenueItemCommandService : IMenueItemCommandService

    {
        private IRealTimeNotifier _realTimeNotifier;

        private Result ValidateAddMenuItemRequest(int categoryId,string nameEn,string nameAr,string imageUrl,decimal price,string description)
        {

            if (categoryId <= 0)
            {
                return Result.Failure("Invalid CategoryId.");
            }
            if (string.IsNullOrEmpty(nameAr) || string.IsNullOrEmpty(nameEn))
            {
                return Result.Failure("NameAr and NameEn cannot be null or empty.");
            }
            if (price <= 0)
            {
                return Result.Failure("Price must be greater than zero.");
            }
            if (string.IsNullOrEmpty(description))
            {
                return Result.Failure("Description cannot be null or empty.");
            }

            return Result.Success(null);
        }
        private readonly IMenueItemRepository _menuItemRepository;
        private readonly ICategoryRepository _categoryRepository;
        public MenueItemCommandService(IMenueItemRepository menuItemRepository, ICategoryRepository categoryRepository, IRealTimeNotifier realTimeNotifier)
        {
            _menuItemRepository = menuItemRepository;
            _categoryRepository = categoryRepository;
            _realTimeNotifier = realTimeNotifier;
        }
        public async Task<Result> AddMenuItemAsync(MenuRecords.AddMenuItemRequest request)
        {
            if (await _categoryRepository.GetCategoryByIdAsync(request.CategoryId) == null) {
                return Result.Failure("Invalid category ID.");
            }
            if (request == null)
            {
                return Result.Failure("Request cannot be null.");
            }
            var validationResult = ValidateAddMenuItemRequest( request.CategoryId, request.NameEn, request.NameAr, request.Emoji, request.Price, request.Description);

            if (!validationResult.IsSuccess)
            {
                return Result.Failure(validationResult.ErrorMessage);

            }
            if (await _menuItemRepository.ItemIsExistsByNameAsync(request.NameEn,request.NameAr, request.CategoryId ))
            {
                return Result.Failure(
                   $"A menu item with the name '{request.NameAr}' or '{request.NameEn}' already exists in this category.",
                   enErrorType.Validation
               );
            }

            var menuItem = MenuItemsMappers.ToEntity(request);

            if (menuItem == null)
            {
                return Result.Failure("Failed to map request to entity.");
            }
           await _menuItemRepository.AddMenuItemAsync(menuItem);
           await _realTimeNotifier.NotifyMenuUpdatedAsync();

            var response = menuItem.ToResponse();
            return Result.Success(response);

        }
        public async Task<Result> UpdateMenuItemAsync(MenuRecords.UpdateMenuItemRequest request)
        {
            if (request == null)
            {
                return Result.Failure("Request cannot be null.");
            }

            if(ValidateAddMenuItemRequest(request.CategoryId, request.NameEn, request.NameAr, request.Emoji, request.Price, request.Description).IsSuccess == false)
            {
                return Result.Failure("Invalid request data.");
            }

            if(request.MenuItemId <= 0)
            {
                return Result.Failure("Invalid MenuItemId.");
            }

             var existingMenuItem = await _menuItemRepository.GetMenuItemByIdAsync(request.MenuItemId);
            if (existingMenuItem == null)
            {
                return Result.Failure($"Menu item with ID {request.MenuItemId} not found.");
            }
            existingMenuItem.CategoryId = request.CategoryId;
            existingMenuItem.NameAr = request.NameAr;
            existingMenuItem.NameEn = request.NameEn;
            existingMenuItem.Description = request.Description;
            existingMenuItem.Price = request.Price;
            existingMenuItem.Emoji = request.Emoji;
            existingMenuItem.IsAvailable = request.IsAvailable;
           await _menuItemRepository.UpdateMenuItemAsync(existingMenuItem);
           await _realTimeNotifier.NotifyMenuUpdatedAsync();

            var response = existingMenuItem.ToResponse();
            return Result.Success(response);

        }
        public async Task<Result> DeleteMenuItemAsync(MenuRecords.DeleteMenuItemRequest request)
        {
            if (request == null)
            {
                return Result.Failure("Request cannot be null.");
            }
            var existingMenuItem = await _menuItemRepository.GetMenuItemByIdAsync(request.MenuItemId);
            if (existingMenuItem == null)
            {
                return Result.Failure($"Menu item with ID {request.MenuItemId} not found.");
            }
            bool hasActiveOrders = await _menuItemRepository.HasActiveOrdersAsync(request.MenuItemId);
            if (hasActiveOrders)
            {
                return Result.Failure(
                    "Cannot delete this menu item because it is currently part of an active order.",
                    enErrorType.Conflict);
            }
            await _menuItemRepository.DeleteMenuItemAsync(existingMenuItem);
            await _realTimeNotifier.NotifyMenuUpdatedAsync();

            return Result.Success(true);
        }

    }
}

﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.MenueItem;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Application.Interfaces.OrdersInterfaces;
using OrderingSystem.Application.Interfaces.SessionsInterfaces;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;

namespace OrderingSystem.Application.Services
{
    public class OrderCommandService : IOrderCommandService
    {
        private readonly IOrderRepository _orderRepository;
        private readonly IMenueItemRepository _menuItemRepository;
        private readonly IRealTimeNotifier _notifier;
        private readonly IDeviceSessionRepository _deviceSessionRepository;

        public OrderCommandService(
            IOrderRepository orderRepository,
            IMenueItemRepository menuItemRepository,
            IRealTimeNotifier notifier,
            IDeviceSessionRepository deviceSessionRepository)
        {
            _orderRepository = orderRepository;
            _menuItemRepository = menuItemRepository;
            _notifier = notifier;
            _deviceSessionRepository = deviceSessionRepository;
        }

        public async Task<Result> AddOrderAsync(OrderRecords.CreateOrderRequest request, Guid deviceSessionId)
        {
            if (request == null)
                return Result.Failure("Request cannot be null.", enErrorType.Validation);

            if (request.TableNumber <= 0)
                return Result.Failure("Table number must be greater than zero.", enErrorType.Validation);

            if (!request.Items.Any())
                return Result.Failure("Order must contain at least one item.", enErrorType.Validation);

            var deviceSession = await _deviceSessionRepository.GetDeviceSessionByIdAsync(deviceSessionId);

            if (deviceSession == null || (!deviceSession.IsApproved && deviceSession.Role != enDeviceRole.Host))
                return Result.Failure("You must be approved by the table host before ordering.", enErrorType.Unauthorized);

            if (deviceSession.TableSession.Table.Status == enTableStatus.Billing)
                return Result.Failure("Orders cannot be placed while the table is processing the bill.", enErrorType.Conflict);

            if (deviceSession.TableSessionId != request.TableSessionId)
                return Result.Failure("The device session does not belong to the requested table session.", enErrorType.Unauthorized);

            // 1. Fetch all items in a single query before the loop
            var requestedItemIds = request.Items.Select(i => i.MenuItemId).Distinct();
            var fetchedItems = await _menuItemRepository.GetMenuItemsByIdsAsync(requestedItemIds);
            var menuItemsDict = fetchedItems.ToDictionary(m => m.MenuItemId);

            decimal totalAmount = 0;
            var orderItems = new List();
            var responseItems = new List();

            foreach (var itemReq in request.Items)
            {
                // 2. Read from the dictionary instead of the database
                if (!menuItemsDict.TryGetValue(itemReq.MenuItemId, out var menuItem) || !menuItem.IsAvailable)
                    return Result.Failure($"Menu item {itemReq.MenuItemId} is unavailable.", enErrorType.Validation);

                totalAmount += menuItem.Price * itemReq.Quantity;

                orderItems.Add(new OrderItem
                {
                    MenuItemId = menuItem.MenuItemId,
                    Quantity = itemReq.Quantity,
                    UnitPrice = menuItem.Price,
                    Notes = itemReq.Notes
                });

                responseItems.Add(new OrderRecords.OrderItemResponse(
                    menuItem.MenuItemId, menuItem.NameEn, menuItem.NameAr, itemReq.Quantity, menuItem.Price, itemReq.Notes));
            }

            var order = new Order
            {
                TableSessionId = request.TableSessionId,
                DeviceSessionId = deviceSessionId,
                TotalAmount = totalAmount,
                OrderStatus = enOrderStatus.Pending,
                CreatedAt = DateTime.UtcNow,
                OrderItems = orderItems
            };

            await _orderRepository.AddOrderAsync(order);
            await _notifier.NotifyCashierOfNewOrderAsync(order.OrderId, order.TableSessionId);

            // --- 3. USE THE PRE-MAPPED LIST ---
            var response = new OrderRecords.OrderResponse(order.OrderId, request.TableNumber, order.TotalAmount, order.OrderStatus, order.CreatedAt, responseItems);

            return Result.Success(response);
        }

        public async Task<Result> ApproveOrderAsync(int orderId)
        {
            var order = await _orderRepository.GetOrderByIdAsync(orderId);
            if (order == null)
                return Result.Failure("Order not found.", enErrorType.NotFound);

            if (order.OrderStatus != enOrderStatus.Pending)
                return Result.Failure("Only pending orders can be approved.", enErrorType.Conflict);

            order.OrderStatus = enOrderStatus.Preparing;
            await _orderRepository.UpdateOrderAsync(order);

            // Notify Customer
            await _notifier.NotifyCustomerOfOrderStatusAsync(order.DeviceSessionId, order.OrderId, order.OrderStatus);

            // Notify Cashier
            await _notifier.NotifyCashiersOfOrderSyncAsync(order.OrderId, order.OrderStatus);

            return Result.Success(true);
        }

        public async Task<Result> CancelOrderAsync(int orderId)
        {
            var order = await _orderRepository.GetOrderByIdAsync(orderId);
            if (order == null)
                return Result.Failure("Order not found.", enErrorType.NotFound);

            await _notifier.NotifyCustomerOfOrderRejectedAsync(order.DeviceSessionId, order.OrderId);

            // Soft delete for auditing purposes
            await _orderRepository.DeleteOrderAsync(order);

            return Result.Success(true);
        }

        public async Task<Result> CancelOrderByCustomerAsync(int orderId, Guid deviceSessionId)
        {
            var order = await _orderRepository.GetOrderByIdAsync(orderId);
            if (order == null)
                return Result.Failure("Order not found.", enErrorType.NotFound);

            // 1. Security Guard
            if (order.DeviceSessionId != deviceSessionId && order.Device.Role != enDeviceRole.Host)
                return Result.Failure("You are not authorized to cancel this order.", enErrorType.Unauthorized);

            // 2. Business Rule Guard
            if (order.OrderStatus != enOrderStatus.Pending)
                return Result.Failure("Your order is already being prepared. Please speak to the cashier to cancel.", enErrorType.Conflict);

            // 3. Execution
            order.OrderStatus = enOrderStatus.Cancelled;
            await _orderRepository.UpdateOrderAsync(order);

            // 4. Notification
            await _notifier.NotifyCashiersOfCustomerCancellationAsync(order.OrderId, order.TableSessionId);
            await _notifier.NotifyCashiersOfOrderSyncAsync(order.OrderId, order.OrderStatus);

            return Result.Success(true);
        }
    }
}

﻿using Microsoft.Extensions.Caching.Memory;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Bills;
using OrderingSystem.Application.Interfaces.Data;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Application.Interfaces.OrdersInterfaces;
using OrderingSystem.Application.Interfaces.SessionsInterfaces;
using OrderingSystem.Application.Interfaces.TableInterfaces;
using OrderingSystem.Application.Interfaces.TableSessionInterfaces;
using OrderingSystem.Application.Interfaces.TaxesInterfaces;
using OrderingSystem.Application.Mappers;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace OrderingSystem.Application.Services
{
    public class SessionCommandService : ISessionCommandService
    {
        private readonly ITableSessionRepository _tableSessionRepository;
        private readonly IDeviceSessionRepository _deviceSessionRepository;
        private readonly ITableRepository _tableRepository;
        private readonly IOrderRepository _orderRepository;
        private readonly ITaxRepository _taxRepository;
        private readonly ITaxCalculationService _taxCalculationService;
        private readonly IBillRepository _billRepository;
        private readonly IUnitOfWork _unitOfWork;
        private readonly IRealTimeNotifier _notifier;
        private readonly IMemoryCache _cache;

        public SessionCommandService(
            ITableSessionRepository tableSessionRepository,
            IDeviceSessionRepository deviceSessionRepository,
            ITableRepository tableRepository,
            IOrderRepository orderRepository,
            ITaxRepository taxRepository,
            ITaxCalculationService taxCalculationService,
            IBillRepository billRepository,
            IUnitOfWork unitOfWork,
            IRealTimeNotifier notifier,
            IMemoryCache cache)
        {
            _tableSessionRepository = tableSessionRepository;
            _deviceSessionRepository = deviceSessionRepository;
            _tableRepository = tableRepository;
            _orderRepository = orderRepository;
            _taxRepository = taxRepository;
            _taxCalculationService = taxCalculationService;
            _billRepository = billRepository;
            _unitOfWork = unitOfWork;
            _notifier = notifier;
            _cache = cache;
        }

        public async Task<Result> ProcessTableQrCodeAsync(string qrCode, Guid? deviceSessionId = null)
        {
            // 1. Cross-Table Interception: Lock the user into their existing active session
            if (deviceSessionId.HasValue)
            {
                var existingDevice = await _deviceSessionRepository.GetDeviceSessionByIdAsync(deviceSessionId.Value);

                if (existingDevice != null && existingDevice.TableSession.Status != enSessionStatus.Closed)
                {
                    // Return their existing session, ignoring the new QR code entirely
                    return Result.Success(existingDevice.TableSession.ToResponse(existingDevice));
                }
            }

            var table = await _tableSessionRepository.GetTableWithActiveSessionAsync(qrCode);

            if (table == null)
            {
                return Result.Failure("Table was not found.", enErrorType.NotFound);
            }

            if (table.Status == enTableStatus.Billing)
            {
                var billingSession = table.Sessions.FirstOrDefault(s => s.ClosedAt == null);
                if (billingSession != null && deviceSessionId.HasValue && billingSession.Devices.Any(d => d.DeviceSessionId == deviceSessionId.Value))
                {
                    return AccessTableSessionAsync(billingSession, deviceSessionId.Value);
                }

                return Result.Failure("This table is currently processing payment. Please wait until it is cleared.", enErrorType.Conflict);
            }

            var activeSession = table.Sessions.FirstOrDefault(s => s.ClosedAt == null && s.Status != enSessionStatus.Closed);

            if (activeSession != null)
            {
                if (deviceSessionId.HasValue && activeSession.Devices.Any(d => d.DeviceSessionId == deviceSessionId.Value))
                {
                    return AccessTableSessionAsync(activeSession, deviceSessionId.Value);
                }

                return await JoinTableSessionAsync(activeSession, Guid.CreateVersion7());
            }

            try
            {
                Result? activationResult = null;

                // --- Transaction Wrapper Added ---
                await _unitOfWork.ExecuteTransactionAsync(async () =>
                {
                    table.Status = enTableStatus.Occupied;
                    await _tableRepository.UpdateTableAsync(table);
                    //activationResult = await ActivateTableSessionAsync(table.TableId, deviceSessionId ?? Guid.CreateVersion7());
                    activationResult = await ActivateTableSessionAsync(table.TableId, Guid.CreateVersion7());
                });

                return activationResult!;
            }
            catch (Exception)
            {
                var refreshedTable = await _tableSessionRepository.GetTableWithActiveSessionAsync(qrCode);
                var newActiveSession = refreshedTable?.Sessions.FirstOrDefault(s => s.ClosedAt == null && s.Status != enSessionStatus.Closed);

                if (newActiveSession != null)
                {
                    return await JoinTableSessionAsync(newActiveSession, deviceSessionId ?? Guid.CreateVersion7());
                }

                throw;
            }
        }

        private async Task<Result> ActivateTableSessionAsync(int tableId, Guid deviceSessionId)
        {
            var tableSession = new TableSession
            {
                TableSessionId = Guid.CreateVersion7(),
                TableId = tableId,
                CreatedAt = DateTime.UtcNow,
                Status = enSessionStatus.PendingActivation,
                ClosedAt = null,
            };

            var deviceSession = new DeviceSession
            {
                DeviceSessionId = deviceSessionId,
                TableSessionId = tableSession.TableSessionId,
                Role = enDeviceRole.Host,
                IsApproved = true,
                TableSession = tableSession,
            };

            await _deviceSessionRepository.AddSessionAsync(deviceSession);
            await _notifier.NotifyCashiersOfActivationAsync(tableId, tableSession.TableSessionId);

            return Result.Success(tableSession.ToResponse(deviceSession));
        }

        private async Task<Result> JoinTableSessionAsync(TableSession tableSession, Guid deviceSessionId)
        {
            var deviceSession = new DeviceSession
            {
                DeviceSessionId = deviceSessionId,
                TableSessionId = tableSession.TableSessionId,
                Role = enDeviceRole.Guest,
                IsApproved = false,
            };

            await _deviceSessionRepository.AddSessionAsync(deviceSession);
            await _notifier.NotifyHostOfGuestJoinAsync(tableSession.TableSessionId, deviceSessionId);

            return Result.Success(SessionsMappers.ToResponse(tableSession, deviceSession));
        }

        private Result AccessTableSessionAsync(TableSession activeSession, Guid deviceSessionId)
        {
            var deviceSession = activeSession.Devices.FirstOrDefault(d => d.DeviceSessionId == deviceSessionId);

            if (deviceSession == null)
            {
                return Result.Failure("Invalid or expired device session", enErrorType.Unauthorized);
            }

            return Result.Success(SessionsMappers.ToResponse(activeSession, deviceSession));
        }

        private void RevokeSessionInCache(Guid tableSessionId)
        {
            _cache.Set($"revoked_table_session_{tableSessionId}", true, TimeSpan.FromHours(4));
        }

        public async Task<Result> ActivateTableSessionAsync(ActivateTableSessionRequest request)
        {
            var session = await _tableSessionRepository.GetSessionByIdAsync(request.tableSessionId);

            if (session == null)
            {
                return Result.Failure("Table session not found.", enErrorType.NotFound);
            }

            if (session.Status != enSessionStatus.PendingActivation)
            {
                return Result.Failure("Session is not pending activation.", enErrorType.Conflict);
            }

            session.Status = enSessionStatus.Active;
            await _tableSessionRepository.UpdateSessionAsync(session);

            var hostDevice = session.Devices.FirstOrDefault(d => d.Role == enDeviceRole.Host);
            if (hostDevice != null)
            {
                await _notifier.NotifyHostOfTableActivationAsync(hostDevice.DeviceSessionId, session.TableSessionId);
            }

            await _notifier.NotifyCashiersOfTableSessionSyncAsync(session.TableSessionId, session.Status);

            return Result.Success(session.ToResponse());
        }

        public async Task<Result> ApproveJoiningRequestAsync(ApproveJoiningSessionRequest request, Guid hostDeviceSessionId)
        {
            var guestDeviceSession = await _deviceSessionRepository.GetDeviceSessionByIdAsync(request.deviceSessionId);
            if (guestDeviceSession == null)
                return Result.Failure("Device session not found.", enErrorType.NotFound);

            var hostDeviceSession = await _deviceSessionRepository.GetDeviceSessionByIdAsync(hostDeviceSessionId);

            if (hostDeviceSession == null ||
                hostDeviceSession.Role != enDeviceRole.Host ||
                hostDeviceSession.TableSessionId != guestDeviceSession.TableSessionId)
            {
                return Result.Failure("Unauthorized to approve guests for this table.", enErrorType.Unauthorized);
            }

            guestDeviceSession.IsApproved = true;
            await _deviceSessionRepository.UpdateDeviceSessionAsync(guestDeviceSession);
            await _notifier.NotifyGuestOfApprovalAsync(guestDeviceSession.DeviceSessionId);

            return Result.Success(SessionsMappers.ToResponse(guestDeviceSession.TableSession, guestDeviceSession));
        }

        public async Task DeactivateTableSessionAsync(Guid tableSessionId)
        {
            var session = await _tableSessionRepository.GetActiveTableSessionWithOrdersAndDevicesAsync(tableSessionId);
            if (session == null)
                return Result.Failure("No active table session was found.", enErrorType.NotFound);

            if (session.Orders != null && session.Orders.Any(o => o.OrderStatus == enOrderStatus.Preparing || o.OrderStatus == enOrderStatus.Served))
            {
                return Result.Failure("Cannot deactivate session: Active orders are being prepared or served.", enErrorType.Conflict);
            }

            // --- Transaction Wrapper Added ---
            await _unitOfWork.ExecuteTransactionAsync(async () =>
            {
                if (session.Orders != null && session.Orders.Any())
                {
                    await _orderRepository.HardDeleteOrdersAsync(session.Orders);
                }

                await _tableSessionRepository.DeleteSessionAsync(session);

                var table = await _tableRepository.GetTableByIdAsync(session.TableId);
                if (table != null)
                {
                    table.Status = enTableStatus.Available;
                    await _tableRepository.UpdateTableAsync(table);
                }
            });

            RevokeSessionInCache(tableSessionId);

            await _notifier.NotifyCashiersOfTableSessionSyncAsync(session.TableSessionId, enSessionStatus.Closed);

            return Result.Success();
        }

        public async Task RequestBillAsync(Guid tableSessionId, Guid deviceSessionId)
        {
            var session = await _tableSessionRepository.GetActiveTableSessionWithOrdersAndDevicesAsync(tableSessionId);
            if (session == null)
                return Result.Failure("No active table session was found.", enErrorType.NotFound);

            var device = session.Devices.FirstOrDefault(d => d.DeviceSessionId == deviceSessionId);
            if (device == null || device.Role != enDeviceRole.Host)
                return Result.Failure("Only the table host is authorized to request the bill.", enErrorType.Unauthorized);

            if (!session.Orders.Any(o => o.OrderStatus == enOrderStatus.Preparing || o.OrderStatus == enOrderStatus.Served))
                return Result.Failure("No approved orders available for billing.", enErrorType.Validation);

            var table = await _tableRepository.GetTableByIdAsync(session.TableId);

            await _notifier.NotifyCashiersOfBillRequestAsync(tableSessionId, table!.TableNumber);
            await _notifier.NotifyGuestsOfBillRequestAsync(tableSessionId);

            table.Status = enTableStatus.Billing;
            await _tableRepository.UpdateTableAsync(table);

            return Result.Success();
        }

        public async Task<Result> EndTableSessionAsync(Guid tableSessionId)
        {
            var session = await _tableSessionRepository.GetActiveTableSessionWithOrdersAndDevicesAsync(tableSessionId);
            if (session == null)
                return Result.Failure("No active table session was found.", enErrorType.NotFound);

            var validOrders = session.Orders.Where(o => o.OrderStatus == enOrderStatus.Preparing || o.OrderStatus == enOrderStatus.Served).ToList();

            if (!validOrders.Any())
            {
                await _unitOfWork.ExecuteTransactionAsync(async () =>
                {
                    session.Status = enSessionStatus.Closed;
                    session.ClosedAt = DateTime.UtcNow;

                    var orphanedPendingOrders = session.Orders.Where(o => o.OrderStatus == enOrderStatus.Pending).ToList();
                    foreach (var orphaned in orphanedPendingOrders) orphaned.OrderStatus = enOrderStatus.Cancelled;
                    if (orphanedPendingOrders.Any()) await _orderRepository.UpdateOrdersAsync(orphanedPendingOrders);

                    await _tableSessionRepository.UpdateSessionAsync(session);

                    var table = await _tableRepository.GetTableByIdAsync(session.TableId);
                    if (table != null)
                    {
                        table.Status = enTableStatus.Available;
                        await _tableRepository.UpdateTableAsync(table);
                    }
                });

                RevokeSessionInCache(tableSessionId);
                await _notifier.NotifyCustomerOfSessionEndedAsync(tableSessionId);
                await _notifier.NotifyCashiersOfTableSessionSyncAsync(session.TableSessionId, enSessionStatus.Closed);

                return Result.Success(session.ToResponse(null));
            }

            var allOrderItems = validOrders.SelectMany(o => o.OrderItems).ToList();

            var consolidatedItems = allOrderItems
                .GroupBy(oi => new { oi.MenuItemId, oi.MenuItem.NameEn, oi.MenuItem.NameAr, oi.UnitPrice })
                .Select(g => new BillItem
                {
                    MenuItemId = g.Key.MenuItemId,
                    NameEn = g.Key.NameEn,
                    NameAr = g.Key.NameAr,
                    UnitPrice = g.Key.UnitPrice,
                    Quantity = g.Sum(oi => oi.Quantity),
                    TotalPrice = g.Key.UnitPrice * g.Sum(oi => oi.Quantity)
                }).ToList();

            decimal totalSubTotal = consolidatedItems.Sum(i => i.TotalPrice);
            int totalItemsCount = consolidatedItems.Sum(i => i.Quantity);

            int uniqueGuestsCount = session.Devices.Count(d => d.IsApproved);

            var activeTaxes = await _taxRepository.GetActiveTaxesAsync();
            var taxResult = _taxCalculationService.CalculateTaxes(totalSubTotal, uniqueGuestsCount, totalItemsCount, activeTaxes);

            var finalBill = new Bill
            {
                TableSessionId = session.TableSessionId,
                TotalSubTotal = totalSubTotal,
                TotalTax = taxResult.TotalTaxAmount,
                GrandTotal = totalSubTotal + taxResult.TotalTaxAmount,
                CreatedAt = DateTime.UtcNow,
                BillItems = consolidatedItems,
                BillTaxes = taxResult.AppliedTaxes.Select(t => new BillTax
                {
                    TaxNameEn = t.NameEn,
                    TaxNameAr = t.NameAr,
                    AppliedAmount = t.Amount
                }).ToList()
            };

            // --- Transaction Wrapper Maintained ---
            await _unitOfWork.ExecuteTransactionAsync(async () =>
            {
                await _billRepository.AddBillAsync(finalBill);

                session.Status = enSessionStatus.Closed;
                session.ClosedAt = DateTime.UtcNow;

                foreach (var order in validOrders) order.OrderStatus = enOrderStatus.Served;
                await _orderRepository.UpdateOrdersAsync(validOrders);

                var orphanedPendingOrders = session.Orders.Where(o => o.OrderStatus == enOrderStatus.Pending).ToList();
                foreach (var orphaned in orphanedPendingOrders) orphaned.OrderStatus = enOrderStatus.Cancelled;
                if (orphanedPendingOrders.Any()) await _orderRepository.UpdateOrdersAsync(orphanedPendingOrders);

                await _tableSessionRepository.UpdateSessionAsync(session);

                var table = await _tableRepository.GetTableByIdAsync(session.TableId);
                if (table != null)
                {
                    table.Status = enTableStatus.Available;
                    await _tableRepository.UpdateTableAsync(table);
                }
            });

            RevokeSessionInCache(tableSessionId);
            await _notifier.NotifyCustomerOfSessionEndedAsync(tableSessionId);
            await _notifier.NotifyCashiersOfTableSessionSyncAsync(session.TableSessionId, enSessionStatus.Closed);

            return Result.Success(session.ToResponse(null));
        }

        public async Task DismissTableSessionAsync(Guid tableSessionId)
        {
            var session = await _tableSessionRepository.GetSessionByIdAsync(tableSessionId);
            if (session == null)
                return Result.Failure("Table session not found.", enErrorType.NotFound);

            if (session.Status != enSessionStatus.PendingActivation)
                return Result.Failure("Session is not pending activation.", enErrorType.Conflict);

            // --- Transaction Wrapper Added ---
            await _unitOfWork.ExecuteTransactionAsync(async () =>
            {
                var table = await _tableRepository.GetTableByIdAsync(session.TableId);
                if (table != null)
                {
                    table.Status = enTableStatus.Available;
                    await _tableRepository.UpdateTableAsync(table);
                }

                session.Status = enSessionStatus.Closed;
                session.ClosedAt = DateTime.UtcNow;
                await _tableSessionRepository.UpdateSessionAsync(session);
            });

            await _notifier.NotifyCustomerOfActivationDismissedAsync(tableSessionId);
            RevokeSessionInCache(tableSessionId);

            return Result.Success();
        }

        public async Task DismissBillAsync(Guid tableSessionId)
        {
            var session = await _tableSessionRepository.GetActiveTableSessionWithOrdersAndDevicesAsync(tableSessionId);
            if (session == null)
                return Result.Failure("No active table session was found.", enErrorType.NotFound);

            var table = await _tableRepository.GetTableByIdAsync(session.TableId);
            if (table == null)
                return Result.Failure("Table not found.", enErrorType.NotFound);

            if (table.Status == enTableStatus.Billing)
            {
                table.Status = enTableStatus.Occupied;
                await _tableRepository.UpdateTableAsync(table);
            }

            await _notifier.NotifyCustomerOfBillRejectedAsync(tableSessionId);
            await _notifier.NotifyCashiersOfBillSyncAsync(tableSessionId);

            return Result.Success();
        }

        public async Task CleanupZombieSessionsAsync(TimeSpan expirationWindow)
        {
            var cutoffTime = DateTime.UtcNow.Subtract(expirationWindow);
            var expiredSessions = await _tableSessionRepository.GetExpiredPendingSessionsAsync(cutoffTime);

            if (!expiredSessions.Any())
                return Result.Success();

            foreach (var session in expiredSessions)
            {
                // --- Transaction Wrapper Added (Per-Session) ---
                await _unitOfWork.ExecuteTransactionAsync(async () =>
                {
                    session.Status = enSessionStatus.Closed;
                    session.ClosedAt = DateTime.UtcNow;

                    if (session.Table != null)
                    {
                        session.Table.Status = enTableStatus.Available;
                        await _tableRepository.UpdateTableAsync(session.Table);
                    }

                    await _tableSessionRepository.UpdateSessionAsync(session);
                });

                await _notifier.NotifyCustomerOfActivationDismissedAsync(session.TableSessionId);
                await _notifier.NotifyCashiersOfZombieSessionClearedAsync(session.TableSessionId);

                RevokeSessionInCache(session.TableSessionId);
            }

            return Result.Success();
        }

        public async Task RejectJoiningRequestAsync(Guid guestDeviceSessionId, Guid hostDeviceSessionId)
        {
            var guestDeviceSession = await _deviceSessionRepository.GetDeviceSessionByIdAsync(guestDeviceSessionId);
            if (guestDeviceSession == null)
                return Result.Failure("Device session not found.", enErrorType.NotFound);

            var hostDeviceSession = await _deviceSessionRepository.GetDeviceSessionByIdAsync(hostDeviceSessionId);

            if (hostDeviceSession == null ||
                hostDeviceSession.Role != enDeviceRole.Host ||
                hostDeviceSession.TableSessionId != guestDeviceSession.TableSessionId)
            {
                return Result.Failure("Unauthorized to reject guests for this table.", enErrorType.Unauthorized);
            }

            // Terminate the session and notify the guest
            await _deviceSessionRepository.DeleteDeviceSessionAsync(guestDeviceSession);
            await _notifier.NotifyGuestOfRejectionAsync(guestDeviceSession.DeviceSessionId);

            return Result.Success();
        }
    }
}

﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.TableInterfaces;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using System.Security.Cryptography;

namespace OrderingSystem.Application.Services
{
    public class TableCommandService : ITableCommandService
    {
        private readonly ITableRepository _tableRepository;

        public TableCommandService(ITableRepository tableRepository)
        {
            _tableRepository = tableRepository;
        }

        public async Task<Result> AddTableAsync(AddTableRequest request)
        {
            var existingTable = await _tableRepository.GetByNumberAndFloorWithDeletedAsync(request.TableNumber, request.FloorNumber);

            if (existingTable != null)
            {
                if (!existingTable.IsDeleted)
                {
                    return Result.Failure(
                        $"Table {request.TableNumber} already exists on Floor {request.FloorNumber}.",
                        enErrorType.Validation);
                }

                var restoredResponse = await RestoreTableAsync(existingTable, request);
                return Result.Success(restoredResponse);
            }

            string uniqueSegment = RandomNumberGenerator.GetHexString(4);
            string generatedQrCode = $"TBL-F{request.FloorNumber}-N{request.TableNumber}-{uniqueSegment}".ToUpper();

            var newTable = new Table
            {
                TableNumber = request.TableNumber,
                FloorNumber = request.FloorNumber,
                QrCode = generatedQrCode,
                Status = enTableStatus.Available
            };

            await _tableRepository.AddTableAsync(newTable);

            var response = new TableResponse(newTable.TableId, newTable.TableNumber, newTable.FloorNumber, newTable.QrCode, newTable.Status, null, newTable.Version);

            return Result.Success(response);
        }

        public async Task<Result> UpdateTableAsync(UpdateTableRequest request)
        {
            var table = await _tableRepository.GetTableByIdAsync(request.TableId);
            if (table == null)
            {
                return Result.Failure("Table not found.", enErrorType.NotFound);
            }

            if ((table.TableNumber != request.TableNumber || table.FloorNumber != request.FloorNumber) &&
                await _tableRepository.ExistsAsync(request.TableNumber, request.FloorNumber))
            {
                return Result.Failure("A table with this number already exists on this floor.", enErrorType.Validation);
            }

            table.TableNumber = request.TableNumber;
            table.FloorNumber = request.FloorNumber;
            table.Status = request.Status;

            await _tableRepository.UpdateTableAsync(table, request.Version);

            var response = new TableResponse(table.TableId, table.TableNumber, table.FloorNumber, table.QrCode, table.Status, null, request.Version);
            return Result.Success(response);
        }

        public async Task DeleteTableAsync(int tableId)
        {
            var table = await _tableRepository.GetTableByIdAsync(tableId);
            if (table == null)
            {
                return Result.Failure("Table not found.", enErrorType.NotFound);
            }

            if (table.Status != enTableStatus.Available)
            {
                return Result.Failure("Cannot delete a table that is currently occupied or billing.", enErrorType.Validation);
            }

            await _tableRepository.DeleteTableAsync(table);
            return Result.Success();
        }

        public async Task<Result> RegenerateQrCode(int tableId)
        {
            var table = await _tableRepository.GetTableByIdAsync(tableId);
            if (table == null)
            {
                return Result.Failure("Table was not found.", enErrorType.NotFound);
            }

            string newUniqueSegment = RandomNumberGenerator.GetHexString(4);
            table.QrCode = $"TBL-F{table.FloorNumber}-N{table.TableNumber}-{newUniqueSegment}".ToUpper();

            await _tableRepository.UpdateTableAsync(table);

            var response = new TableResponse(table.TableId, table.TableNumber, table.FloorNumber, table.QrCode, table.Status, null, table.Version);
            return Result.Success(response);
        }

        private async Task RestoreTableAsync(Table existingTable, AddTableRequest request)
        {
            existingTable.IsDeleted = false;
            existingTable.Status = enTableStatus.Available;

            string newUniqueSegment = RandomNumberGenerator.GetHexString(4);
            existingTable.QrCode = $"TBL-F{request.FloorNumber}-N{request.TableNumber}-{newUniqueSegment}".ToUpper();

            await _tableRepository.UpdateTableAsync(existingTable);

            return new TableResponse(
                existingTable.TableId,
                existingTable.TableNumber,
                existingTable.FloorNumber,
                existingTable.QrCode,
                existingTable.Status,
                null,
                existingTable.Version
            );
        }
    }
}

﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.TaxesInterfaces;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using System;
using System.Collections.Generic;

namespace OrderingSystem.Application.Services
{
    public class TaxCalculationService : ITaxCalculationService
    {
        public (List AppliedTaxes, decimal TotalTaxAmount) CalculateTaxes(
            decimal subTotal,
            int uniqueGuestsCount,
            int totalItemsCount,
            IEnumerable activeTaxes)
        {
            var appliedTaxes = new List();
            decimal totalTaxAmount = 0m;

            var guestCount = uniqueGuestsCount > 0 ? uniqueGuestsCount : 1;

            foreach (var tax in activeTaxes)
            {
                decimal taxAmount = 0m;

                if (tax.TaxType == enTaxType.Percentage)
                {
                    if (tax.TaxScope == enTaxScope.PerBill)
                        taxAmount = subTotal * (tax.Amount / 100m);
                }
                else if (tax.TaxType == enTaxType.FlatRate)
                {
                    if (tax.TaxScope == enTaxScope.PerBill)
                        taxAmount = tax.Amount;
                    else if (tax.TaxScope == enTaxScope.PerGuest)
                        taxAmount = tax.Amount * guestCount;
                    else if (tax.TaxScope == enTaxScope.PerItem)
                        taxAmount = tax.Amount * totalItemsCount;
                }

                if (taxAmount > 0)
                {
                    // Standard rounding away from zero
                    var roundedAmount = Math.Round(taxAmount, 2, MidpointRounding.AwayFromZero);
                    appliedTaxes.Add(new AppliedTaxResponse(tax.NameEn, tax.NameAr, roundedAmount));
                    totalTaxAmount += roundedAmount;
                }
            }

            return (appliedTaxes, totalTaxAmount);
        }

        public decimal CalculateGuestTaxAmount(decimal guestSubTotal, int guestItemsCount, int totalGuestsCount, IEnumerable activeTaxes)
        {
            decimal guestTaxAmount = 0m;
            var guestCount = totalGuestsCount > 0 ? totalGuestsCount : 1;

            foreach (var tax in activeTaxes)
            {
                decimal taxAmount = 0m;
                if (tax.TaxType == enTaxType.Percentage && tax.TaxScope == enTaxScope.PerBill)
                    taxAmount = guestSubTotal * (tax.Amount / 100m); // % of THEIR subtotal
                else if (tax.TaxType == enTaxType.FlatRate)
                {
                    if (tax.TaxScope == enTaxScope.PerBill) taxAmount = tax.Amount / guestCount; // Split flat bill fee
                    else if (tax.TaxScope == enTaxScope.PerGuest) taxAmount = tax.Amount; // Their guest fee
                    else if (tax.TaxScope == enTaxScope.PerItem) taxAmount = tax.Amount * guestItemsCount; // Their items
                }

                guestTaxAmount += Math.Round(taxAmount, 2, MidpointRounding.AwayFromZero);
            }
            return guestTaxAmount;
        }
    }
}

﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Application.Interfaces.TaxesInterfaces;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;

public class TaxCommandService : ITaxCommandService
{
    private readonly ITaxRepository _taxRepository;
    private readonly IRealTimeNotifier _notifier;

    public TaxCommandService(ITaxRepository taxRepository, IRealTimeNotifier notifier)
    {
        _taxRepository = taxRepository;
        _notifier = notifier;
    }

    public async Task<Result> AddTaxAsync(TaxRecords.AddTaxRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.NameEn) || string.IsNullOrWhiteSpace(request.NameAr))
            return Result.Failure("Names cannot be empty.");
        if (request.Amount < 0)
            return Result.Failure("Amount cannot be negative.");
        if (request.TaxType == enTaxType.Percentage && request.TaxScope != enTaxScope.PerBill)
            return Result.Failure("Percentage taxes can only be applied to the entire bill.", enErrorType.Validation);
        if (await _taxRepository.TaxExistsByNameAsync(request.NameEn, request.NameAr))
            return Result.Failure("A tax with this name already exists.", enErrorType.Conflict);

        var tax = new Tax { NameAr = request.NameAr, NameEn = request.NameEn, Amount = request.Amount, TaxType = request.TaxType, TaxScope = request.TaxScope, IsActive = request.IsActive };
        await _taxRepository.AddTaxAsync(tax);

        await _notifier.NotifyTaxesUpdatedAsync();

        return Result.Success(new TaxRecords.TaxResponse(tax.TaxId, tax.NameAr, tax.NameEn, tax.Amount, tax.TaxType, tax.TaxScope, tax.IsActive));
    }

    public async Task<Result> UpdateTaxAsync(TaxRecords.UpdateTaxRequest request)
    {
        var tax = await _taxRepository.GetTaxByIdAsync(request.TaxId);
        if (tax == null) return Result.Failure("Tax not found.", enErrorType.NotFound);

        if (request.TaxType == enTaxType.Percentage && request.TaxScope != enTaxScope.PerBill)
            return Result.Failure("Percentage taxes can only be applied to the entire bill.", enErrorType.Validation);

        tax.NameAr = request.NameAr;
        tax.NameEn = request.NameEn;
        tax.Amount = request.Amount;
        tax.TaxType = request.TaxType;
        tax.TaxScope = request.TaxScope;
        tax.IsActive = request.IsActive;

        await _taxRepository.UpdateTaxAsync(tax);

        await _notifier.NotifyTaxesUpdatedAsync();

        return Result.Success(new TaxRecords.TaxResponse(tax.TaxId, tax.NameAr, tax.NameEn, tax.Amount, tax.TaxType, tax.TaxScope, tax.IsActive));
    }

    public async Task<Result> DeleteTaxAsync(int taxId)
    {
        var tax = await _taxRepository.GetTaxByIdAsync(taxId);
        if (tax == null) return Result.Failure("Tax not found.", enErrorType.NotFound);

        tax.IsDeleted = true;
        tax.IsActive = false;
        await _taxRepository.UpdateTaxAsync(tax);

        await _notifier.NotifyTaxesUpdatedAsync();

        return Result.Success(true);
    }
}

﻿using OrderingSystem.Domain.Enums;
using System;
using System.Collections.Generic;
using System.Text;

namespace OrderingSystem.Domain.Common
{
    public class Result
    {
        public bool IsSuccess { get; }
        public string? ErrorMessage { get; }
        public enErrorType ErrorType { get; }

        protected Result(bool isSuccess, string? errorMessage, enErrorType errorType)
        {
            IsSuccess = isSuccess;
            ErrorMessage = errorMessage;
            ErrorType = errorType;
        }

        public static Result Success() => new(true, null, enErrorType.None);
        public static Result Failure(string message, enErrorType errorType = enErrorType.Failure)
            => new(false, message, errorType);
    }

    public class Result : Result
    {
        public T? Value { get; }

        private Result(T? value, bool isSuccess, string? errorMessage, enErrorType errorType)
            : base(isSuccess, errorMessage, errorType)
        {
            Value = value;
        }

        public static Result Success(T value) => new(value, true, null, enErrorType.None);
        public static new Result Failure(string message, enErrorType errorType = enErrorType.Failure)
            => new(default, false, message, errorType);
    }
}

