﻿using Microsoft.EntityFrameworkCore;
using Npgsql;
using OrderingSystem.Application.Interfaces.Data;
using System;

namespace OrderingSystem.Infrastructure.Data
{
    public class PostgresErrorMapper : IDatabaseErrorMapper
    {
        public string? MapDbUpdateException(Exception exception)
        {
            if (exception is DbUpdateException dbUpdateEx && dbUpdateEx.InnerException is PostgresException pgEx)
            {
                return pgEx.SqlState switch
                {
                    PostgresErrorCodes.UniqueViolation => "A record with this information already exists.",
                    PostgresErrorCodes.ForeignKeyViolation => "This operation failed because the record is either currently in use or references missing data.",
                    PostgresErrorCodes.CheckViolation => "The provided data violates a business rule constraint.",
                    PostgresErrorCodes.NotNullViolation => "A required piece of information was missing.",
                    _ => "A database constraint was violated."
                };
            }
            return null;
        }

        public bool IsConnectionError(Exception exception)
        {
            return exception is NpgsqlException;
        }
    }
}

﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;

namespace OrderingSystem.Infrastructure.Data
{
    public class OrderingSystemDbContext : DbContext
    {
        public OrderingSystemDbContext(DbContextOptions options)
            : base(options)
        {
        }

        public DbSet Users { get; set; }
        public DbSet Tables { get; set; }
        public DbSet TableSessions { get; set; }
        public DbSet Categories { get; set; }
        public DbSet MenuItems { get; set; }
        public DbSet SessionDevices { get; set; }
        public DbSet Orders { get; set; }
        public DbSet OrderItems { get; set; }
        public DbSet Taxes { get; set; }
        public DbSet Bills { get; set; }
        public DbSet BillItems { get; set; }
        public DbSet BillTaxes { get; set; }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);

            // 1. Users
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.UserId);
                entity.Property(e => e.FullName).IsRequired().HasMaxLength(255);
                entity.Property(e => e.PasswordHash).IsRequired();
                entity.Property(e => e.Role).IsRequired();
                entity.Property(e => e.RefreshToken)
                      .HasMaxLength(255)
                      .IsRequired(false);
                entity.Property(e => e.RefreshTokenExpiryTime)
                      .IsRequired(false);
                entity.Property(e => e.AbsoluteRefreshTokenExpiryTime)
                      .IsRequired(false);
            });

            // 2. Tables
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.TableId);
                entity.Property(e => e.TableNumber).IsRequired();
                entity.Property(e => e.FloorNumber).IsRequired();
                entity.Property(e => e.Status).IsRequired();
                entity.Property(e => e.QrCode).IsRequired().HasMaxLength(255);
                entity.Property(e => e.IsDeleted).IsRequired();

                entity.Property(e => e.Version)
                      .IsRowVersion()
                      .HasColumnName("xmin");

                entity.HasMany(t => t.Sessions)
                      .WithOne(ts => ts.Table)
                      .HasForeignKey(ts => ts.TableId)
                      .OnDelete(DeleteBehavior.Restrict);

                entity.HasQueryFilter(e => !e.IsDeleted);

                entity.HasIndex(t => new { t.TableNumber, t.FloorNumber })
                      .IsUnique()
                      .HasFilter("\"IsDeleted\" = false");
            });

            // 3. TableSessions
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.TableSessionId);

                entity.HasOne(e => e.Table)
                      .WithMany(t => t.Sessions)
                      .HasForeignKey(e => e.TableId)
                      .OnDelete(DeleteBehavior.Restrict);

                entity.HasIndex(s => new { s.TableId, s.ClosedAt }, "IX_TableSessions_TableId")
                      .HasFilter(@"""ClosedAt"" IS NULL")
                      .IsUnique();
            });

            // 4. Categories
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.CategoryId);
                entity.Property(e => e.NameAr).HasMaxLength(255);
                entity.Property(e => e.NameEn).HasMaxLength(255);
                entity.Property(e => e.IsDeleted).IsRequired();

                entity.HasQueryFilter(e => !e.IsDeleted);
            });

            // 5. MenuItems
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.MenuItemId);
                entity.Property(e => e.Price).HasPrecision(18, 2);
                entity.Property(e => e.NameAr).HasMaxLength(255);
                entity.Property(e => e.NameEn).HasMaxLength(255);

                entity.Property(e => e.Emoji).HasMaxLength(50).IsRequired(false);

                entity.Property(e => e.IsDeleted).IsRequired();

                entity.HasOne(e => e.Category)
                      .WithMany(c => c.MenuItems)
                      .HasForeignKey(e => e.CategoryId)
                      .OnDelete(DeleteBehavior.Restrict);

                entity.HasQueryFilter(e => !e.IsDeleted);

                entity.HasIndex(m => new { m.CategoryId, m.IsAvailable, m.IsDeleted });
            });

            // 6. DeviceSession
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.DeviceSessionId);

                entity.HasOne(e => e.TableSession)
                      .WithMany(s => s.Devices)
                      .HasForeignKey(e => e.TableSessionId)
                      .OnDelete(DeleteBehavior.Cascade);
            });

            // 7. Orders
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.OrderId);
                entity.Property(e => e.TotalAmount).HasPrecision(18, 2);

                entity.HasOne(e => e.Session)
                      .WithMany(s => s.Orders)
                      .HasForeignKey(e => e.TableSessionId)
                      .OnDelete(DeleteBehavior.Restrict);

                entity.HasOne(e => e.Device)
                      .WithMany(d => d.Orders)
                      .HasForeignKey(e => e.DeviceSessionId)
                      .OnDelete(DeleteBehavior.Restrict);

                entity.HasQueryFilter(e => e.OrderStatus != enOrderStatus.Cancelled);

                entity.HasIndex(o => new { o.OrderStatus, o.CreatedAt });

                entity.ToTable(t => t.HasCheckConstraint("CK_Order_TotalAmount_NonNegative", "\"TotalAmount\" >= 0"));
            });

            // 8. OrderItems
            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.OrderItemId);
                entity.Property(e => e.UnitPrice).HasPrecision(18, 2);
                entity.Property(e => e.Notes);

                entity.HasOne(e => e.Order)
                      .WithMany(o => o.OrderItems)
                      .HasForeignKey(e => e.OrderId)
                      .OnDelete(DeleteBehavior.Cascade);

                entity.HasOne(e => e.MenuItem)
                      .WithMany(m => m.OrderItems)
                      .HasForeignKey(e => e.MenuItemId)
                      .OnDelete(DeleteBehavior.Restrict);

                entity.ToTable(t =>
                {
                    t.HasCheckConstraint("CK_OrderItem_Quantity_Positive", "\"Quantity\" > 0");
                    t.HasCheckConstraint("CK_OrderItem_UnitPrice_NonNegative", "\"UnitPrice\" >= 0");
                });
            });

            modelBuilder.Entity(entity =>
            {
                entity.HasKey(e => e.TaxId);
                entity.Property(e => e.NameAr).HasMaxLength(255).IsRequired();
                entity.Property(e => e.NameEn).HasMaxLength(255).IsRequired();
                entity.Property(e => e.Amount).HasPrecision(18, 2).IsRequired();
                entity.Property(e => e.IsDeleted).IsRequired();
                entity.HasQueryFilter(e => !e.IsDeleted);
                entity.ToTable(t => t.HasCheckConstraint("CK_Tax_Amount_NonNegative", "\"Amount\" >= 0"));
            });

            modelBuilder.Entity(entity => {
                entity.HasKey(e => e.BillId);
                entity.Property(e => e.TotalSubTotal).HasPrecision(18, 2);
                entity.Property(e => e.TotalTax).HasPrecision(18, 2);
                entity.Property(e => e.GrandTotal).HasPrecision(18, 2);
                entity.HasOne(e => e.TableSession).WithOne(ts => ts.FinalBill)
                      .HasForeignKey(e => e.TableSessionId).OnDelete(DeleteBehavior.Restrict);
            });

            modelBuilder.Entity(entity => {
                entity.HasKey(e => e.BillItemId);
                entity.Property(e => e.UnitPrice).HasPrecision(18, 2);
                entity.Property(e => e.TotalPrice).HasPrecision(18, 2);
                entity.HasOne(e => e.Bill).WithMany(b => b.BillItems)
                      .HasForeignKey(e => e.BillId).OnDelete(DeleteBehavior.Cascade);
            });

            modelBuilder.Entity(entity => {
                entity.HasKey(e => e.BillTaxId);
                entity.Property(e => e.AppliedAmount).HasPrecision(18, 2);
                entity.HasOne(e => e.Bill).WithMany(b => b.BillTaxes)
                      .HasForeignKey(e => e.BillId).OnDelete(DeleteBehavior.Cascade);
            });
        }
    }
}

﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Application.Interfaces.Data;
using System;
using System.Threading.Tasks;

namespace OrderingSystem.Infrastructure.Data
{
    public class UnitOfWork : IUnitOfWork
    {
        private readonly OrderingSystemDbContext _context;

        public UnitOfWork(OrderingSystemDbContext context)
        {
            _context = context;
        }

        public async Task ExecuteTransactionAsync(Func action)
        {
            var strategy = _context.Database.CreateExecutionStrategy();
            await strategy.ExecuteAsync(async () =>
            {
                using var transaction = await _context.Database.BeginTransactionAsync();
                try
                {
                    await action();
                    await transaction.CommitAsync();
                }
                catch
                {
                    await transaction.RollbackAsync();
                    throw; // Let the GlobalExceptionHandler catch it
                }
            });
        }
    }
}

﻿using Microsoft.AspNetCore.SignalR;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Infrastructure.ExternalServices.Notifications;
using OrderingSystem.Domain.Enums;

namespace OrderingSystem.Infrastructure.Notifications
{
    public class SignalRNotifier : IRealTimeNotifier
    {
        private readonly IHubContext _hubContext;

        public SignalRNotifier(IHubContext hubContext)
        {
            _hubContext = hubContext;
        }

        public async Task NotifyCashiersOfActivationAsync(int tableId, Guid tableSessionId)
        {
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveActivationRequest(tableId, tableSessionId, $"Table {tableId} is requesting activation.");
        }

        public async Task NotifyHostOfGuestJoinAsync(Guid tableSessionId, Guid guestDeviceSessionId)
        {
            // The Host's frontend will have called JoinTableSessionGroup with this ID
            await _hubContext.Clients.Group(tableSessionId.ToString())
                .ReceiveJoinRequest(guestDeviceSessionId, "A new guest is requesting to join your table.");
        }

        public async Task NotifyGuestOfApprovalAsync(Guid guestDeviceSessionId)
        {
            // The Guest's frontend will have called RegisterDeviceGroup with this ID
            await _hubContext.Clients.Group(guestDeviceSessionId.ToString())
                .ReceiveHostApprovalNotification("Your request to join the table has been approved.");
        }

        public async Task NotifyHostOfTableActivationAsync(Guid hostDeviceSessionId, Guid tableSessionId)
        {
            // The Host connects to a group named after their DeviceSessionId while waiting
            await _hubContext.Clients.Group(hostDeviceSessionId.ToString())
                    .ReceiveCashierApprovalNotification(tableSessionId, "Your table has been approved by the cashier and is now active.");
        }

        public async Task NotifyCashierOfNewOrderAsync(int orderId, Guid tableSessionId)
        {
            // Target the cashiers group
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveNewOrderNotification(orderId, tableSessionId, $"New order #{orderId} received.");
        }

        public async Task NotifyCustomerOfOrderStatusAsync(Guid deviceSessionId, int orderId, enOrderStatus status)
        {
            // Target the specific device session
            await _hubContext.Clients.Group(deviceSessionId.ToString())
                .ReceiveOrderStatusUpdate(orderId, status, $"Your order #{orderId} is now {status}.");
        }

        public async Task NotifyCashiersOfCustomerCancellationAsync(int orderId, Guid tableSessionId)
        {
            // Alert the cashiers that an order was dropped
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveOrderStatusUpdate(orderId, enOrderStatus.Cancelled, $"Order #{orderId} was cancelled by the customer.");
        }

        public async Task NotifyCashiersOfBillRequestAsync(Guid tableSessionId, int tableNumber)
        {
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveBillRequestNotification(tableSessionId, tableNumber, $"Table {tableNumber} is requesting the bill.");
        }

        public async Task NotifyMenuUpdatedAsync()
        {
            // Broadcasting to All ensures every active customer app refreshes the menu
            await _hubContext.Clients.All.ReceiveMenuUpdated("The menu has been updated.");
        }
        public async Task NotifyCustomerOfActivationDismissedAsync(Guid tableSessionId)
        {
            await _hubContext.Clients.Group(tableSessionId.ToString())
                .ReceiveActivationDismissed("Table activation was dismissed.");
        }

        public async Task NotifyCustomerOfBillRejectedAsync(Guid tableSessionId)
        {
            await _hubContext.Clients.Group(tableSessionId.ToString())
                .ReceiveBillRejected("Your bill request was rejected.");
        }

        public async Task NotifyCustomerOfOrderRejectedAsync(Guid deviceSessionId, int orderId)
        {
            await _hubContext.Clients.Group(deviceSessionId.ToString())
                .ReceiveOrderRejected(orderId, "Your order request was rejected.");
        }

        public async Task NotifyCustomerOfSessionEndedAsync(Guid tableSessionId)
        {
            // Target the specific table session group so all devices at the table get it
            await _hubContext.Clients.Group(tableSessionId.ToString())
                .ReceiveSessionEnded("The table session has been closed. Thank you!");
        }

        public async Task NotifyGuestsOfBillRequestAsync(Guid tableSessionId)
        {
            // Target the group containing ALL devices (Host + Guests) at this specific table
            await _hubContext.Clients.Group(tableSessionId.ToString())
                .ReceiveBillRequested(tableSessionId.ToString());
        }
        public async Task NotifyTaxesUpdatedAsync()
        {
            await _hubContext.Clients.All.ReceiveTaxesUpdated("The taxes configuration has been updated.");
        }
        public async Task NotifyGuestOfRejectionAsync(Guid guestDeviceSessionId)
        {
            await _hubContext.Clients.Group(guestDeviceSessionId.ToString())
                .ReceiveHostRejectionNotification("Your request to join the table has been rejected.");
        }
        public async Task NotifyCashiersOfZombieSessionClearedAsync(Guid tableSessionId)
        {
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveZombieSessionCleared(tableSessionId, "A pending session expired and was automatically cleared.");
        }
        public async Task NotifyCashiersOfOrderSyncAsync(int orderId, enOrderStatus status)
        {
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveCashierOrderSync(orderId, status, $"Order #{orderId} status changed to {status}.");
        }
        public async Task NotifyCashiersOfTableSessionSyncAsync(Guid tableSessionId, enSessionStatus status)
        {
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveCashierTableSessionSync(tableSessionId, status, $"Table session status changed to {status}.");
        }
        public async Task NotifyCashiersOfBillSyncAsync(Guid tableSessionId)
        {
            await _hubContext.Clients.Group(TableSessionNotificationsHub.GroupNames.Cashiers)
                .ReceiveCashierBillSync(tableSessionId, "The bill request was processed by another cashier.");
        }
    }
}

﻿using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.SignalR;
using OrderingSystem.Application.Interfaces.Notifications;
using OrderingSystem.Domain.Enums;
using System.Security.Claims;

namespace OrderingSystem.Infrastructure.ExternalServices.Notifications
{
    [Authorize]
    public class TableSessionNotificationsHub : Hub
    {
        public static class GroupNames
        {
            public const string Cashiers = "Group_Cashiers";
            public const string Waiters = "Group_Waiters";
        }

        public override async Task OnConnectedAsync()
        {
            var user = Context.User;
            if (user?.Identity?.IsAuthenticated != true)
            {
                Context.Abort();
                return;
            }

            // 1. Staff Group Routing
            var role = user.FindFirst(ClaimTypes.Role)?.Value ?? user.FindFirst("role")?.Value;
            if (!string.IsNullOrEmpty(role))
            {
                if (role == enRoleType.Cashier.ToString() || role == enRoleType.Admin.ToString())
                {
                    await Groups.AddToGroupAsync(Context.ConnectionId, GroupNames.Cashiers);
                }
                else if (role == enRoleType.Waiter.ToString())
                {
                    await Groups.AddToGroupAsync(Context.ConnectionId, GroupNames.Waiters);
                }

                await base.OnConnectedAsync();
                return;
            }

            // 2. Customer Group Routing (Derived straight from claims)
            var deviceSessionId = user.FindFirst("DeviceSessionId")?.Value;
            var tableSessionId = user.FindFirst("TableSessionId")?.Value;

            if (!string.IsNullOrEmpty(deviceSessionId) && !string.IsNullOrEmpty(tableSessionId))
            {
                await Groups.AddToGroupAsync(Context.ConnectionId, deviceSessionId);
                await Groups.AddToGroupAsync(Context.ConnectionId, tableSessionId);

                await base.OnConnectedAsync();
                return;
            }

            // Abort if identity lacks appropriate claims
            Context.Abort();
        }
    }
}

