﻿using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.DTOs.Paged;
using OrderingSystem.Application.Interfaces.OrdersInterfaces;
using OrderingSystem.Application.Interfaces.TaxesInterfaces;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Enums;
using OrderingSystem.Infrastructure.Data;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using static OrderingSystem.Application.DTOs.OrderRecords;

namespace OrderingSystem.Infrastructure.Queries
{
    public class OrderQuery : IOrderQuery
    {
        private readonly OrderingSystemDbContext _context;
        private readonly ITaxCalculationService _taxCalculationService;
        private readonly IConfiguration _config;

        public OrderQuery(OrderingSystemDbContext context, ITaxCalculationService taxCalculationService, IConfiguration config)
        {
            _context = context;
            _taxCalculationService = taxCalculationService;
            _config = config;
        }

        // دالة مساعدة لحساب بداية ونهاية اليوم المحلي بدقة وتحويلها لـ UTC
        private (DateTime StartUtc, DateTime EndUtc) GetLocalDayBoundsUtc()
        {
            // سحب المنطقة الزمنية من الإعدادات، مع وضع دمشق كقيمة افتراضية للحماية
            var tzId = _config["RestaurantSettings:TimeZoneId"] ?? "Asia/Damascus";
            var tz = TimeZoneInfo.FindSystemTimeZoneById(tzId);

            // حساب الوقت المحلي الآن
            var localNow = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, tz);

            // تصفير الوقت للحصول على منتصف الليل المحلي (بداية اليوم)
            var localStartOfDay = localNow.Date;

            // تحويل البداية والنهاية إلى UTC لاستخدامها في البحث
            var startUtc = TimeZoneInfo.ConvertTimeToUtc(localStartOfDay, tz);
            var endUtc = startUtc.AddDays(1);

            return (startUtc, endUtc);
        }

        public async Task<Result<PagedResponse>> GetPendingOrdersAsync(PageDTO page)
        {
            var query = _context.Orders
                .AsNoTracking()
                .Include(o => o.OrderItems)
                    .ThenInclude(oi => oi.MenuItem)
                .Where(o => o.OrderStatus == enOrderStatus.Pending);

            var totalRecords = await query.CountAsync();

            var items = await query
                .OrderBy(o => o.CreatedAt)
                .Skip((page.PageNumber - 1) * page.PageSize)
                .Take(page.PageSize)
                .Select(o => new OrderRecords.OrderResponse(
                    o.OrderId,
                    o.Session.Table.TableNumber,
                    o.TotalAmount,
                    o.OrderStatus,
                    o.CreatedAt,
                    o.OrderItems.Select(oi => new OrderRecords.OrderItemResponse(
                        oi.MenuItemId,
                        oi.MenuItem != null ? oi.MenuItem.NameEn : "Deleted Item",
                        oi.MenuItem != null ? oi.MenuItem.NameAr : "عنصر محذوف",
                        oi.Quantity,
                        oi.UnitPrice,
                        oi.Notes
                    )).ToList()
                ))
                .ToListAsync();

            var pagedResponse = new PagedResponse(items, totalRecords, page.PageNumber, page.PageSize);
            return Result<PagedResponse>.Success(pagedResponse);
        }

        public async Task<Result<List>> GetTopThreeItemsTodayAsync()
        {
            var bounds = GetLocalDayBoundsUtc();

            var rawItems = await _context.OrderItems
                .AsNoTracking()
                .Where(oi => oi.Order.CreatedAt >= bounds.StartUtc &&
                             oi.Order.CreatedAt < bounds.EndUtc &&
                             oi.Order.OrderStatus != enOrderStatus.Cancelled)
                .Where(oi => !oi.MenuItem.IsDeleted)
                .GroupBy(oi => new
                {
                    oi.MenuItemId,
                    oi.MenuItem.NameEn,
                    oi.MenuItem.NameAr
                })
                .Select(g => new
                {
                    g.Key.MenuItemId,
                    g.Key.NameEn,
                    g.Key.NameAr,
                    TotalQuantity = g.Sum(oi => oi.Quantity)
                })
                .OrderByDescending(r => r.TotalQuantity)
                .Take(3)
                .ToListAsync();

            var itemsList = rawItems
                .Select(x => new OrderRecords.OrderItemResponse(
                    x.MenuItemId,
                    x.NameEn,
                    x.NameAr,
                    x.TotalQuantity,
                    0m,
                    string.Empty
                ))
                .ToList();

            return Result<List>.Success(itemsList);
        }

        public async Task<Result> GetCountOfPendingOrder()
        {
            try
            {
                var count = await _context.Orders
                    .Where(o => o.OrderStatus == enOrderStatus.Pending)
                    .CountAsync();

                return Result.Success(count);
            }
            catch (Exception ex)
            {
                return Result.Failure($"Error when fetching pending order count: {ex.Message}");
            }
        }

        public async Task<Result> GetCountOfOrders()
        {
            try
            {
                var bounds = GetLocalDayBoundsUtc();

                var count = await _context.Orders
                    .Where(o => o.CreatedAt >= bounds.StartUtc && o.CreatedAt < bounds.EndUtc)
                    .CountAsync();

                return Result.Success(count);
            }
            catch (Exception ex)
            {
                return Result.Failure($"Error when fetching today's order count: {ex.Message}");
            }
        }

        public async Task<Result<PagedResponse>> GetOrdersByDateRangeAsync(DateTime startDate, DateTime endDate, PageDTO page)
        {
            var query = _context.Orders
                .AsNoTracking()
                .Include(o => o.OrderItems)
                    .ThenInclude(oi => oi.MenuItem)
                .Where(o => o.CreatedAt >= startDate && o.CreatedAt <= endDate);

            var totalRecords = await query.CountAsync();

            var items = await query
                .OrderByDescending(o => o.CreatedAt)
                .Skip((page.PageNumber - 1) * page.PageSize)
                .Take(page.PageSize)
                .Select(o => new OrderRecords.OrderResponse(
                    o.OrderId,
                    o.Session.Table.TableNumber,
                    o.TotalAmount,
                    o.OrderStatus,
                    o.CreatedAt,
                    o.OrderItems.Select(oi => new OrderRecords.OrderItemResponse(
                        oi.MenuItemId,
                        oi.MenuItem != null ? oi.MenuItem.NameEn : "Deleted Item",
                        oi.MenuItem != null ? oi.MenuItem.NameAr : "عنصر محذوف",
                        oi.Quantity,
                        oi.UnitPrice,
                        oi.Notes
                    )).ToList()
                ))
                .ToListAsync();

            var pagedResponse = new PagedResponse(items, totalRecords, page.PageNumber, page.PageSize);
            return Result<PagedResponse>.Success(pagedResponse);
        }

        public async Task<Result<PagedResponse>> GetHistoricalBillsAsync(DateTime startDate, DateTime endDate, PageDTO page)
        {
            var query = _context.Bills
                .IgnoreQueryFilters()
                .Include(b => b.TableSession)
                    .ThenInclude(ts => ts.Table)
                .Include(b => b.BillItems)
                .Include(b => b.BillTaxes)
                .Where(b => b.CreatedAt >= startDate && b.CreatedAt <= endDate)
                .OrderByDescending(b => b.CreatedAt);

            var totalRecords = await query.CountAsync();
            var bills = await query
                .Skip((page.PageNumber - 1) * page.PageSize)
                .Take(page.PageSize)
                .ToListAsync();

            var responseData = bills.Select(b => new HistoricalBillResponse(
                OrderId: b.BillId,
                TableNumber: b.TableSession.Table.TableNumber,
                TableSessionId: b.TableSessionId.ToString(),
                Status: "Closed",
                CreatedAt: b.CreatedAt,
                TotalSubTotal: b.TotalSubTotal,
                GrandTotal: b.GrandTotal,
                Items: b.BillItems.Select(bi => new OrderRecords.BillItemResponse(
                    bi.MenuItemId, bi.NameAr, bi.NameEn, bi.Quantity, bi.UnitPrice, bi.TotalPrice
                )).ToList(),
                AppliedTaxes: b.BillTaxes.Select(bt => new AppliedTaxResponse(
                    bt.TaxNameEn, bt.TaxNameAr, bt.AppliedAmount
                )).ToList()
            )).ToList();

            return Result<PagedResponse>.Success(
                new PagedResponse(responseData, totalRecords, page.PageNumber, page.PageSize)
            );
        }
    }
}

﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.DTOs.Paged;
using OrderingSystem.Application.Interfaces.TableInterfaces;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Enums;
using OrderingSystem.Infrastructure.Data;
using System;
using System.Linq;
using System.Threading.Tasks;

namespace OrderingSystem.Infrastructure.Queries
{
    public class TableQuery : ITableQuery
    {
        private readonly OrderingSystemDbContext _context;

        public TableQuery(OrderingSystemDbContext context)
        {
            _context = context;
        }

        public async Task GetTableQrCodeAsync(int tableId)
        {
            return await _context.Tables
                .AsNoTracking()
                .Where(t => t.TableId == tableId)
                .Select(t => t.QrCode)
                .FirstOrDefaultAsync();
        }

        public async Task GetTableByIdAsync(int tableId)
        {
            var table = await _context.Tables
                .AsNoTracking()
                .Where(t => t.TableId == tableId)
                .Select(t => new TableResponse(
                    t.TableId,
                    t.TableNumber,
                    t.FloorNumber,
                    t.QrCode,
                    t.Status,
                    (t.Status == enTableStatus.Occupied || t.Status == enTableStatus.Billing)
                        ? t.Sessions.Where(s => s.ClosedAt == null).Select(s => (Guid?)s.TableSessionId).FirstOrDefault()
                        : null
                ))
                .FirstOrDefaultAsync();
            return table;
        }

        public async Task GetTableByNumberAsync(int tableNumber, int floorNumber)
        {
            var table = await _context.Tables
                .AsNoTracking()
                .Where(t => t.TableNumber == tableNumber && t.FloorNumber == floorNumber)
                .Select(t => new TableResponse(
                    t.TableId,
                    t.TableNumber,
                    t.FloorNumber,
                    t.QrCode,
                    t.Status,
                    (t.Status == enTableStatus.Occupied || t.Status == enTableStatus.Billing)
                        ? t.Sessions.Where(s => s.ClosedAt == null).Select(s => (Guid?)s.TableSessionId).FirstOrDefault()
                        : null,
                    t.Version
                ))
                .FirstOrDefaultAsync();
            return table;
        }

        public async Task<PagedResponse> GetAllTablesByFloorAsync(PageDTO page, int floorNumber)
        {
            var query = _context.Tables
                .AsNoTracking()
                .Where(t => t.FloorNumber == floorNumber);

            var totalRecords = await query.CountAsync();
            var tables = await query
                .Skip((page.PageNumber - 1) * page.PageSize)
                .Take(page.PageSize)
                .Select(t => new TableResponse(
                    t.TableId,
                    t.TableNumber,
                    t.FloorNumber,
                    t.QrCode,
                    t.Status,
                    (t.Status == enTableStatus.Occupied || t.Status == enTableStatus.Billing)
                        ? t.Sessions.Where(s => s.ClosedAt == null).Select(s => (Guid?)s.TableSessionId).FirstOrDefault()
                        : null,
                    EF.Property(t, "Version")
                ))
                .ToListAsync();

            return new PagedResponse(tables, totalRecords, page.PageNumber, page.PageSize);
        }

        public async Task<PagedResponse> GetAllTablesAsync(PageDTO page)
        {
            var query = _context.Tables.AsNoTracking();
            var totalRecords = await query.CountAsync();

            var tables = await query
                .Skip((page.PageNumber - 1) * page.PageSize)
                .Take(page.PageSize)
                .Select(t => new TableResponse(
                    t.TableId,
                    t.TableNumber,
                    t.FloorNumber,
                    t.QrCode,
                    t.Status,
                    (t.Status == enTableStatus.Occupied || t.Status == enTableStatus.Billing)
                        ? t.Sessions.Where(s => s.ClosedAt == null).Select(s => (Guid?)s.TableSessionId).FirstOrDefault()
                        : null,
                    t.Version
                ))
                .ToListAsync();

            return new PagedResponse(tables, totalRecords, page.PageNumber, page.PageSize);
        }

        public async Task<PagedResponse> GetAllTablesByStatusAsync(PageDTO page, enTableStatus tableStatus)
        {
            var query = _context.Tables
                .AsNoTracking()
                .Where(t => t.Status == tableStatus);

            var totalRecords = await query.CountAsync();

            var tables = await query
                .Skip((page.PageNumber - 1) * page.PageSize)
                .Take(page.PageSize)
                .Select(t => new TableResponse(
                    t.TableId,
                    t.TableNumber,
                    t.FloorNumber,
                    t.QrCode,
                    t.Status,
                    (t.Status == enTableStatus.Occupied || t.Status == enTableStatus.Billing)
                        ? t.Sessions.Where(s => s.ClosedAt == null).Select(s => (Guid?)s.TableSessionId).FirstOrDefault()
                        : null,
                    t.Version
                ))
                .ToListAsync();

            return new PagedResponse(tables, totalRecords, page.PageNumber, page.PageSize);
        }

        public async Task<PagedResponse> GetAllPendingActivationTablesAsync(PageDTO page)
        {
            var query = _context.Tables
                .AsNoTracking()
                .Where(t => t.Status == enTableStatus.Occupied && t.Sessions.Any(s => s.Status == enSessionStatus.PendingActivation && s.ClosedAt == null));

            var totalRecords = await query.CountAsync();

            var tables = await query
                    .Skip((page.PageNumber - 1) * page.PageSize)
                    .Take(page.PageSize)
                    .Select(t => new PendingTableResponse(
                        t.TableId,
                        t.TableNumber,
                        t.FloorNumber,
                        t.QrCode,
                        t.Status,
                        t.Sessions
                            .Where(s => s.Status == enSessionStatus.PendingActivation && s.ClosedAt == null)
                            .Select(s => s.TableSessionId)
                            .FirstOrDefault(),
                        t.Sessions
                            .Where(s => s.Status == enSessionStatus.PendingActivation && s.ClosedAt == null)
                            .Select(s => (DateTime?)s.CreatedAt)
                            .FirstOrDefault()
                    ))
                    .ToListAsync();

            return new PagedResponse(tables, totalRecords, page.PageNumber, page.PageSize);
        }

        public async Task<PagedResponse> GetAllBillingTablesAsync(PageDTO page)
        {
            var query = _context.Tables
                .AsNoTracking()
                .Where(t => t.Status == enTableStatus.Billing && t.Sessions.Any(s => s.ClosedAt == null));

            var totalRecords = await query.CountAsync();

            var tables = await query
                    .Skip((page.PageNumber - 1) * page.PageSize)
                    .Take(page.PageSize)
                    .Select(t => new PendingTableResponse(
                        t.TableId,
                        t.TableNumber,
                        t.FloorNumber,
                        t.QrCode,
                        t.Status,
                        t.Sessions
                            .Where(s => s.ClosedAt == null)
                            .Select(s => s.TableSessionId)
                            .FirstOrDefault(),
                        t.Sessions
                            .Where(s => s.ClosedAt == null)
                            .Select(s => (DateTime?)s.CreatedAt)
                            .FirstOrDefault()
                    ))
                    .ToListAsync();

            return new PagedResponse(tables, totalRecords, page.PageNumber, page.PageSize);
        }

        public async Task<Result> GetCountOfOccupiedTables()
        {
            try
            {
                var count = await _context.Tables
                    .Where(t => t.Status == enTableStatus.Occupied)
                    .CountAsync();

                return Result.Success(count);
            }
            catch (Exception ex)
            {
                return Result.Failure($"Error when fetching count of occupied tables: {ex.Message}");
            }
        }

        public async Task<Result> GetCountTable()
        {
            try
            {
                var count = await _context.Tables
                    .AsNoTracking()
                    .Where(t => !t.IsDeleted)
                    .CountAsync();

                return Result.Success(count);
            }
            catch (Exception ex)
            {
                return Result.Failure($"Error when fetching count of tables: {ex.Message}");
            }
        }
    }
}

﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.TableSessionInterfaces;
using OrderingSystem.Application.Interfaces.TaxesInterfaces;
using OrderingSystem.Application.Mappers;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using OrderingSystem.Infrastructure.Data;

namespace OrderingSystem.Infrastructure.Queries
{
    public class TableSessionQuery : ITableSessionQuery
    {
        private readonly OrderingSystemDbContext _context;
        private readonly ITaxCalculationService _taxCalculationService;

        public TableSessionQuery(OrderingSystemDbContext context, ITaxCalculationService taxCalculationService)
        {
            _context = context;
            _taxCalculationService = taxCalculationService;
        }

        public async Task GetActiveSessionByTableAsync(int tableId)
        {
            // Bypasses entity tracking and maps directly from SQL to your DTO.
            // This eliminates the need for your SessionsMappers.cs on the read path entirely.
            return await _context.TableSessions
                    .AsNoTracking()
                    .Where(s => s.TableId == tableId && s.ClosedAt == null)
                    .Select(s => new TableSessionResponse(
                        s.TableSessionId,
                        s.Table.TableNumber,
                        s.Status,
                        s.CreatedAt
                    ))
                    .FirstOrDefaultAsync();
        }

        public async Task GetBillSummaryAsync(Guid tableSessionId)
        {
            var session = await _context.TableSessions
                .AsNoTracking()
                .Include(s => s.Orders.Where(o => o.OrderStatus == enOrderStatus.Preparing || o.OrderStatus == enOrderStatus.Served))
                    .ThenInclude(o => o.OrderItems)
                        .ThenInclude(oi => oi.MenuItem)
                .Include(s => s.Devices)
                .FirstOrDefaultAsync(s => s.TableSessionId == tableSessionId);

            if (session == null) return null;

            var activeTaxes = await _context.Taxes
                .AsNoTracking()
                .Where(t => t.IsActive && !t.IsDeleted)
                .ToListAsync();

            decimal totalSubTotal = 0;
            var guestBills = new List();
            int totalItemsCount = 0;

            var approvedGuestsCount = session.Devices.Count(d => d.IsApproved);

            foreach (var device in session.Devices)
            {
                var deviceOrders = session.Orders.Where(o => o.DeviceSessionId == device.DeviceSessionId).ToList();
                if (!deviceOrders.Any()) continue;

                decimal guestSubTotal = 0;
                int guestItemsCount = 0;

                var billItems = deviceOrders.SelectMany(o => o.OrderItems)
                    .GroupBy(oi => oi.MenuItemId)
                    .Select(g =>
                    {
                        var first = g.First();
                        var qty = g.Sum(i => i.Quantity);
                        var itemTotal = qty * first.UnitPrice;

                        guestSubTotal += itemTotal;
                        totalItemsCount += qty;
                        guestItemsCount += qty;

                        return new BillItemResponse(
                            first.MenuItemId,
                            first.MenuItem?.NameEn ?? "Deleted",
                            first.MenuItem?.NameAr ?? "محذوف",
                            qty,
                            first.UnitPrice,
                            itemTotal
                        );
                    }).ToList();

                totalSubTotal += guestSubTotal;

                // --- 3. CALCULATE SPLIT TOTALS & PASS TO CONSTRUCTOR ---
                decimal guestTax = _taxCalculationService.CalculateGuestTaxAmount(
                                    guestSubTotal,
                                    guestItemsCount,
                                    approvedGuestsCount,
                                    activeTaxes);

                decimal guestGrandTotal = guestSubTotal + guestTax;

                guestBills.Add(new GuestBillResponse(device.DeviceSessionId, device.Role, billItems, guestSubTotal, guestTax, guestGrandTotal));
            }

            var uniqueGuests = session.Devices.Count;

            var taxResult = _taxCalculationService.CalculateTaxes(totalSubTotal, approvedGuestsCount, totalItemsCount, activeTaxes);
            var grandTotal = totalSubTotal + taxResult.TotalTaxAmount;

            return new BillSummaryResponse(
                tableSessionId,
                guestBills,
                totalSubTotal,
                taxResult.AppliedTaxes,
                grandTotal
            );
        }
        public async Task GetSessionPollingStatusAsync(Guid tableSessionId, Guid deviceSessionId)
        {
            return await _context.SessionDevices
                .AsNoTracking()
                .Where(d => d.DeviceSessionId == deviceSessionId && d.TableSessionId == tableSessionId)
                .Select(d => new SessionPollingResponse(
                    d.TableSession.Status,
                    d.IsApproved
                ))
                .FirstOrDefaultAsync();
        }
    }
}

﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.DTOs.Paged;
using OrderingSystem.Application.Interfaces.TaxesInterfaces;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Enums;
using OrderingSystem.Infrastructure.Data;
using System;
using System.Collections.Generic;
using System.Text;

namespace OrderingSystem.Infrastructure.Queries
{
    public class TaxQuery : ITaxQuery
    {
        private readonly OrderingSystemDbContext _context;
        public TaxQuery(OrderingSystemDbContext context) => _context = context;

        public async Task<Result<PagedResponse>> GetAllTaxesAsync(PageDTO page)
        {
            var query = _context.Taxes.AsNoTracking();
            var totalRecords = await query.CountAsync();
            var items = await query.Skip((page.PageNumber - 1) * page.PageSize).Take(page.PageSize)
                .Select(t => new TaxRecords.TaxResponse(t.TaxId, t.NameAr, t.NameEn, t.Amount, t.TaxType, t.TaxScope, t.IsActive))
                .ToListAsync();

            return Result<PagedResponse>.Success(new PagedResponse(items, totalRecords, page.PageNumber, page.PageSize));
        }

        public async Task<Result> GetTaxByIdAsync(int taxId)
        {
            var tax = await _context.Taxes.AsNoTracking()
                .Where(t => t.TaxId == taxId)
                .Select(t => new TaxRecords.TaxResponse(t.TaxId, t.NameAr, t.NameEn, t.Amount, t.TaxType, t.TaxScope, t.IsActive))
                .FirstOrDefaultAsync();

            return tax == null ? Result.Failure("Tax not found.", enErrorType.NotFound) : Result.Success(tax);
        }
    }
}

