﻿using OrderingSystem.Application.DTOs;
using OrderingSystem.Application.Interfaces.Category;
using OrderingSystem.Infrastructure.Data;
using OrderingSystem.Domain.Common;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using System;
using System.Collections.Generic;
using System.Text;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

namespace OrderingSystem.Infrastructure.Repositories
{
    public class CategoryRepository : ICategoryRepository
    {
        private readonly OrderingSystemDbContext _dbContext;

        public CategoryRepository(OrderingSystemDbContext dbContext)
        {
            _dbContext = dbContext;
        }

        public async Task AddCategoryAsync(Category category)
        {
            _dbContext.Categories.Add(category);
            await _dbContext.SaveChangesAsync();
        }

        public async Task UpdateCategoryAsync(Category category)
        {
            _dbContext.Categories.Update(category);
            await _dbContext.SaveChangesAsync();
        }

        public async Task DeleteCategoryAsync(Category category)
        {
            if (category == null) return false;

            // 1. Soft delete the parent category
            category.IsDeleted = true;
            category.IsAvailable = false;

            // 2. Cascade the soft delete to all associated menu items
            var menuItems = await _dbContext.MenuItems
                .Where(m => m.CategoryId == category.CategoryId)
                .ToListAsync();

            foreach (var item in menuItems)
            {
                item.IsDeleted = true;
                item.IsAvailable = false;
            }

            _dbContext.Categories.Update(category);
            _dbContext.MenuItems.UpdateRange(menuItems);

            await _dbContext.SaveChangesAsync();
            return true;
        }

        public async Task GetCategoryByIdAsync(int categoryId)
        {
            return await _dbContext.Categories.FirstOrDefaultAsync(c => c.CategoryId == categoryId);

        }

        public async Task GetCategoryExistsAsync(int categoryId)
        {
            return await _dbContext.Categories.AnyAsync(c => c.CategoryId == categoryId);
        }

        public async Task CategoryIsExistsByNameAsync(string nameEn, string nameAr)
        {
            return await _dbContext.Categories
                .AsNoTracking()
                .AnyAsync(c => c.NameEn.ToLower() == nameEn.ToLower() ||
                               c.NameAr.ToLower() == nameAr.ToLower());
        }

        public async Task HasActiveOrdersAsync(int categoryId)
        {
            // Checks if any menu item belonging to this category is currently
            // locked inside an order that hasn't been served or cancelled yet.
            return await _dbContext.OrderItems
                .AnyAsync(oi => oi.MenuItem.CategoryId == categoryId &&
                               (oi.Order.OrderStatus == enOrderStatus.Pending ||
                                oi.Order.OrderStatus == enOrderStatus.Preparing));
        }
    }
}

