        {
            return await _dbContext.OrderItems
                .AnyAsync(oi => oi.MenuItemId == menuItemId &&
                               (oi.Order.OrderStatus == enOrderStatus.Pending ||
                                oi.Order.OrderStatus == enOrderStatus.Preparing));
        }
