﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Application.Interfaces.TableInterfaces;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using OrderingSystem.Infrastructure.Data;

namespace OrderingSystem.Infrastructure.Repositories
{
    public class TableRepository : ITableRepository
    {
        private readonly OrderingSystemDbContext _context;

        public TableRepository(OrderingSystemDbContext context)
        {
            _context = context;
        }

        public async Task AddTableAsync(Table table)
        {
            _context.Tables.Add(table);
            await _context.SaveChangesAsync();
        }

        public async Task UpdateTableAsync(Table table, uint? originalVersion = null)
        {
            _context.Tables.Update(table);

            // Only override the tracker if the frontend sent a specific version to check against
            if (originalVersion.HasValue)
            {
                _context.Entry(table).Property(e => e.Version).OriginalValue = originalVersion.Value;
            }

            await _context.SaveChangesAsync();
        }

        public async Task DeleteTableAsync(Table table)
        {
            table.IsDeleted = true;
            table.Status = enTableStatus.Available;

            _context.Tables.Update(table);
            await _context.SaveChangesAsync();
        }

        public async Task ExistsAsync(int tableNumber, int floor)
        {
            return await _context.Tables.AnyAsync(t => t.TableNumber == tableNumber && t.FloorNumber == floor);
        }

        public async Task GetTableByIdAsync(int tableId)
        {
            return await _context.Tables.FirstOrDefaultAsync(t => t.TableId == tableId);
        }

        public async Task GetByNumberAndFloorWithDeletedAsync(int tableNumber, int floor)
        {
            return await _context.Tables
                .IgnoreQueryFilters()
                .FirstOrDefaultAsync(t => t.TableNumber == tableNumber && t.FloorNumber == floor);
        }
    }
}

﻿using Microsoft.EntityFrameworkCore;
using OrderingSystem.Domain.Entities;
using OrderingSystem.Domain.Enums;
using OrderingSystem.Infrastructure.Data;
using OrderingSystem.Application.Interfaces.TableSessionInterfaces;

namespace OrderingSystem.Infrastructure.Repositories
{
    public class TableSessionRepository : ITableSessionRepository
    {
        private readonly OrderingSystemDbContext _context;

        public TableSessionRepository(OrderingSystemDbContext context)
        {
            _context = context;
        }

        public async Task GetTableWithActiveSessionAsync(string qrCode)
        {
            // Fetches the domain entity for business rule validation in the Command service.
            // Includes the Session navigation property so you can check table.Session != null.
            return await _context.Tables
                    .Include(t => t.Sessions.Where(s => s.Status != enSessionStatus.Closed))
                    .ThenInclude(s => s.Devices)
                    .FirstOrDefaultAsync(t => t.QrCode == qrCode);
        }

        public async Task GetActiveTableSessionWithOrdersAndDevicesAsync(Guid tableSessionId)
        {
            return await _context.TableSessions
                .IgnoreQueryFilters() // Bypasses the IsDeleted filter so legacy checkout data maps correctly
                .Include(s => s.Orders)
                    .ThenInclude(o => o.OrderItems).ThenInclude(oi => oi.MenuItem)
                .Include(s => s.Devices)
                .FirstOrDefaultAsync(s => s.TableSessionId == tableSessionId && s.ClosedAt == null);
        }

        public async Task AddSessionAsync(TableSession session)
        {
            _context.TableSessions.Add(session);
            await _context.SaveChangesAsync();
        }

       public async Task GetSessionByIdAsync(Guid tableSessionId)
        {
            return await _context.TableSessions
                .Include(s => s.Devices)
                .FirstOrDefaultAsync(s => s.TableSessionId == tableSessionId);
        }

        public async Task UpdateSessionAsync(TableSession session)
        {
                _context.TableSessions.Update(session);
            await _context.SaveChangesAsync();
        }

        public async Task DeleteSessionAsync(TableSession session)
        {
            _context.TableSessions.Remove(session);
            await _context.SaveChangesAsync();
        }

        public async Task<List> GetExpiredPendingSessionsAsync(DateTime cutoffTime)
        {
            return await _context.TableSessions
                .Include(s => s.Table)
                .Where(s => s.Status == enSessionStatus.PendingActivation
                         && s.ClosedAt == null
                         && s.CreatedAt <= cutoffTime)
                .ToListAsync();
        }
    }
}

